/* ==========================================================================
   尘世命轨 · 小手机        v1.9.1-dbfix1
   酒馆助手独立脚本（现装在本角色卡内，角色级）

   功能
     · 仙网   —— 对应变量「互联网」：风闻 / 论坛 / 日报 三栏目、点赞、评论预览、AI 刷新、AI 续帖
     · 传讯   —— 对应变量「讯息」：联系人与未读、搜索、删除消息 / 联系人、AI 回复；
                 并读取当前酒馆聊天记录（正文里的 [说|角色|情绪|内容]），在联系人详情里
                 给出「剧情发言」，同时作为 AI 回复的依据
     · 股市   —— 与原卡状态栏「交易」页同价的行情（沪深 + 纳斯达克）、持仓盈亏，
                 让 AI 自行操盘（按正文楼层自动 + 手动），写回 主角.资产
     · 设置   —— 三套生成配置各自独立（仙网 / 传讯 / 股市）；模型来源分「与插头相同 / 自定义」，
                 自定义下可「获取模型」（拉 {base}/models）与存取模型预设（对应 MVU 的 API 方案）

   v1.9.3：传讯按联系人分离「讯息」变量 —— 写回变量时新增「收件人」字段，
        导入会话时严格按 收件人/键名 归属：主角发给 A 的消息不再出现在 B 的聊天里，
        旧数据里归不了属的主角消息也不再每个会话都塞。
        新增「清空记录」（单个联系人：本地 + 变量同步清，之后的新消息仍可正常收发）；
        设置页「清空聊天记录」现在会同步清空「讯息」变量（以前只清本地，几轮后又被导回）。

   v1.9.4：仙网「刷新」按钮实装 —— 不再只是重绘界面，而是对 风闻 / 论坛 / 日报
        三个栏目各跑一次 AI 生成（全栏刷新）；「AI 刷新仙网」仍只刷当前栏目。
        AI 未启用时「刷新」退化为原来的只刷新显示。

   v1.9.5：仙网刷新拆成分栏按钮 —— 「刷 风闻」「刷 论坛」「刷 日报」各只调 1 次模型
        （按量计费的站点省钱），「全栏刷新」保留（连调 3 次）。
        原来的「AI 刷新仙网」（刷当前栏）按钮由分栏按钮取代。

   界面修订（v1.9.5-ui.x，只动样式与排版，不动数据与流程）
     · ui.4：去掉四个页面标题右上角的方框字（原 .ph-page-seal 印章块）。
     · ui.5：股市页重做 —— 账户总览 / 指数卡 / 涨跌跑马灯 / 分时折线 / 委托量条；
              并修复「下单量」标签被 flex 拉伸压窄导致的错位（裸 span.ph-chip → 独立标签块）。
     · ui.6：通讯录与聊天页显示头像。顺序：角色档案「头像」字段 ＞
              图床的 default 头像 ＞ 同名角色卡 ＞ 名字首字。图床沿用原卡状态栏那一套约定
              （assets/charactor_avatar/<角色名>/ 下的 <角色名>_avatar.png 与
              <角色名>_avatar_default.png 都归 default，带 _avatar_smile 这类后缀的算表情图；
              索引读 assets/manifest.json，读不到退 GitHub tree API；缓存优先复用状态栏写的那份）。
              角色卡头像走酒馆缩略图接口 ctx.getThumbnailUrl('avatar', ch.avatar)。
              另修掉一处老问题：「从 MVU 导入」读的 SillyTavern.extension_settings
              在新版酒馆已不存在，改为优先走 getContext().extensionSettings。
     · ui.7：头像逻辑重构 —— 移除「图床根地址」「图床没有这位时」两个设置与「当前状态」诊断；
              同名角色卡只认当前正在聊的那一张，不再扫角色库里的其它卡；
              persona 头像按酒馆自己的优先级读取（本聊天锁定 ＞ 当前活动 ＞ 默认 ＞ 第一个），
              修掉之前只读 default_persona 导致取不到当前人设图的问题。
     · ui.8：删掉头像设置组里那段「取图顺序 / 图床命名 / 单独指定」的说明文字。

   打开方式（v1.9.0 起）
     · 默认「成就式浮窗」：仿原卡成就系统的浮窗 —— 居中、1px 渐变描边、暗色内衬、
       全屏模糊遮罩，点遮罩 / 按 Esc / 点 ✕ 关闭。这是页面内的浮层，不开新窗口。
     · 「小面板(拖动左上角可改变大小)」：贴右下角的小卡片，可拖动、位置记忆。
     · v1.9.0：删除「浏览器独立窗口」模式（原来的 window.open + postMessage 桥接）。
       旧档里 launch='window' 会自动迁移为 'float'。

   ★ v1.8.2 定位方案（参照成就系统 V5）：把悬浮球与面板从「CSS 摆位」改为
        「JS 实测自校准摆位」：
        · 挂载后先按视口算默认坐标 → 用 getBoundingClientRect 实测渲染位置 →
          反推环境偏移（页面 transform / zoom / 滚动 / iframe 等一切因素之和）→
          用 left/top 把球与面板钉到期望视口坐标。
        · 位置数据从「屏幕坐标」改成「视口坐标 + 视口快照」（存储 key 为 .v2），
          换设备 / 换方向时按视口比例换算，不再跑出屏幕。
        · v1.9.1：悬浮球初始位置改为「成就系统悬浮球的正上方」（手机端、桌面端一致）。
        · 新增「重置小手机位置」脚本按钮，与成就系统的「重置位置」一一对应。
        · 面板 / 遮罩同思路自校准，避免手机端打开后上半部分溢出到屏幕外。

   设计要点
     · 生成走 ST 后端 generateRaw(custom_api)，避免浏览器直连的 CORS 问题；
       该 API 不可用时自动回退到内置 fetch（OpenAI 兼容 /chat/completions）。
     · 设置与聊天记录存在脚本文变量 $phone 里，不进提示词；UI 状态存 localStorage。
     · 回帖/发消息通过 Mvu.replaceMvuData 写回最新助手楼层，与原卡状态栏同一套写法。
     · UI 必须画到 window.parent（酒馆主页面）：本脚本运行在一个 display:none 的
       srcdoc iframe 里，画在自己文档里是看不见的。
   ========================================================================== */
'use strict';

const PHONE_VERSION = '1.9.5-ui.8';
const POS_FAB_KEY = 'csmg.phone.fab.v2';       /* ★ v2：存「期望视口坐标 + 视口快照」 */
const POS_PANEL_KEY = 'csmg.phone.panel.v2';   /* ★ v2：面板（面板模式）位置 */
const POS_PANEL_SIZE_KEY = 'csmg.phone.panel.size.v1';  /* ★ 面板模式下用户调整的尺寸 */
const UI_KEY = 'csmg.phone.ui.v1';
const LOOK_KEY = 'csmg.look.v1';
const SCRIPT_OPT = { type: 'script' };
const VAR_ROOT = '$phone';
const BTN_NAME = '打开手机';
const RESET_BTN_NAME = '重置小手机位置';

/* ============================== 基础工具 ============================== */
const hostDoc = () => { try { return (window.parent && window.parent.document) || document; } catch (e) { return document; } };
const hostWin = () => { try { return window.parent || window; } catch (e) { return window; } };

/* ★ v1.9.1：手机端让输入框失焦、收起小键盘
   场景：用户从聊天记录（或任何聚焦过输入框的状态）里点悬浮球 / 脚本按钮，
   触摸事件的默认行为会把 ST 的输入框重新唤醒。这里主动 blur 一次，
   再用 setTimeout 补一次，覆盖手机端“延迟自动聚焦”的情况。 */
function dismissKeyboard() {
  try {
    const doc = hostDoc();
    const active = doc.activeElement;
    if (active && active !== doc.body && active !== doc.documentElement && typeof active.blur === 'function') {
      active.blur();
    }
    const candidates = ['#send_textarea', '#send_textarea_alt', 'textarea#send_textarea', 'textarea#send_textarea_gs'];
    for (const sel of candidates) {
      const el = doc.querySelector(sel);
      if (el && typeof el.blur === 'function') el.blur();
    }
  } catch (e) {}
}
const esc = v => String(v === null || v === undefined ? '' : v).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const obj = v => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const rows = v => Object.entries(obj(v));
const val = (v, f = '') => (v === '' || v === null || v === undefined) ? f : v;
const num = (v, f = 0) => Number.isFinite(Number(v)) ? Number(v) : f;
const arr = v => Array.isArray(v) ? v : (v === '' || v === null || v === undefined ? [] : [v]);
const clamp = (v, a, b) => Math.max(a, Math.min(b, num(v, a)));
const pick = (o, keys) => { const x = obj(o); for (const k of keys) { if (x[k] !== undefined && x[k] !== '' && x[k] !== null && typeof x[k] !== 'object') return x[k]; } return ''; };
const pad2 = n => String(n).padStart(2, '0');
const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 7);

let toastTimer = null;
/** 提示：页面内面板有 #ph-toast 时直接显示 */
function toast(msg, ms) {
  const text = String(msg);
  try {
    const el = hostDoc().getElementById('ph-toast');
    if (el) {
      el.textContent = text;
      el.classList.add('on');
      clearTimeout(toastTimer);
      toastTimer = setTimeout(() => el.classList.remove('on'), ms || 2400);
    }
  } catch (e) {}
  if (!hostDoc().getElementById('ph-toast')) console.warn('[小手机]', text);
}

/* ============================== ★ 视口与位置 ============================== */
/* 参照成就系统 V5：不用 position:fixed 的 CSS 摆位——挂载后实测元素渲染位置，反推
   环境偏移（页面 transform / zoom / 滚动 / iframe 等一切因素之和），用 JS 把元素钉在
   期望的「视口坐标」上。滚动/缩放/换向自动重钉。位置以视口坐标 + 视口快照存取，
   换设备或换方向时按比例换算。 */

function hostViewport() {
  try {
    const w = hostWin();
    return { w: w.innerWidth || 360, h: w.innerHeight || 640 };
  } catch (e) { return { w: 360, h: 640 }; }
}

/** 读「视口坐标」位置（带视口比例换算）；读不到或格式非法返回 null */
function readViewportPos(key) {
  try {
    const raw = JSON.parse(hostWin().localStorage.getItem(key) || 'null');
    if (!raw || !Number.isFinite(raw.x) || !Number.isFinite(raw.y)) return null;
    const { w, h } = hostViewport();
    let x = raw.x, y = raw.y;
    if (raw.vw > 0 && raw.vh > 0 && (Math.abs(raw.vw - w) > 2 || Math.abs(raw.vh - h) > 2)) {
      x = raw.x * (w / raw.vw);
      y = raw.y * (h / raw.vh);
    }
    return { x: x, y: y };
  } catch (e) { return null; }
}

function writeViewportPos(key, x, y) {
  try {
    const { w, h } = hostViewport();
    hostWin().localStorage.setItem(key, JSON.stringify({ x: x, y: y, vw: w, vh: h }));
  } catch (e) {}
}

/**
 * 小手机悬浮球的默认位置（视口坐标）：成就系统悬浮球的正上方，间距 8px。
 *   · 手机端（视口宽度 ≤ 820）：成就系统悬浮球尺寸 46px，
 *     位置 x = w - 46 - 12，y = h - 46 - 96
 *   · 桌面端：成就系统悬浮球尺寸 46px，
 *     位置 x = w - 46 - 16，y = h - 46 - 16（对应 CSS right:16px; bottom:16px）
 *   小手机的水平中心与成就球对齐；竖直方向小手机底边 = 成就球顶边 - 8。
 */
function defaultFabPos(rect) {
  const { w, h } = hostViewport();
  const small = w <= 820;
  const fabW = rect && rect.width > 0 ? rect.width : 46;
  const fabH = rect && rect.height > 0 ? rect.height : 46;
  const achSize = 46;
  const gap = 8;
  const achX = small ? (w - achSize - 12) : (w - achSize - 16);
  const achY = small ? (h - achSize - 96) : (h - achSize - 16);
  /* 水平中心对齐成就球；竖直放到成就球正上方 */
  return {
    x: achX + (achSize - fabW) / 2,
    y: achY - fabH - gap,
  };
}

let desiredFab = null;      /* 悬浮球的期望视口坐标；null = 用默认 */
let desiredPanel = null;    /* 面板模式下面板的期望视口坐标；null = 用默认 */
let desiredPanelSize = null;/* ★ 面板模式下用户调整后的尺寸 { w, h }；null = 用默认 */
let repinQueued = false;

/* ★ 面板尺寸的读写：只存像素值，应用时再按当前视口夹回，换设备不会跑飞 */
function readPanelSize() {
  try {
    const raw = JSON.parse(hostWin().localStorage.getItem(POS_PANEL_SIZE_KEY) || 'null');
    if (!raw || !Number.isFinite(raw.w) || !Number.isFinite(raw.h)) return null;
    return { w: raw.w, h: raw.h };
  } catch (e) { return null; }
}
function writePanelSize(w, h) {
  try { hostWin().localStorage.setItem(POS_PANEL_SIZE_KEY, JSON.stringify({ w: w, h: h })); } catch (e) {}
}

/**
 * ★ 核心：悬浮球实测渲染位置 → 反推环境偏移 → 钉到期望视口坐标。
 *   fixed 正常时偏移为 0（原行为）；被 transform / zoom 劫持时同样精确命中。
 */
function pinFab() {
  const doc = hostDoc();
  const fab = doc.getElementById('ph-fab');
  if (!fab || !fab.isConnected) return;
  /* 首次测量前先显式设 left/top=0，避免测量结果里混入 right/bottom 的定位 */
  if (!fab.style.left) { fab.style.left = '0px'; fab.style.top = '0px'; }
  fab.style.right = 'auto';
  fab.style.bottom = 'auto';
  const rect = fab.getBoundingClientRect();
  if (!rect || rect.width < 4 || rect.height < 4) return;
  const { w, h } = hostViewport();
  if (!desiredFab) {
    desiredFab = readViewportPos(POS_FAB_KEY) || defaultFabPos(rect);
  }
  /* 夹回视口内 */
  desiredFab.x = Math.min(Math.max(4, desiredFab.x), Math.max(4, w - rect.width - 4));
  desiredFab.y = Math.min(Math.max(4, desiredFab.y), Math.max(4, h - rect.height - 4));
  const curL = parseFloat(fab.style.left || '0') || 0;
  const curT = parseFloat(fab.style.top || '0') || 0;
  const offX = rect.left - curL; /* 环境偏移：容器 transform / 滚动等一切因素之和 */
  const offY = rect.top - curT;
  fab.style.left = (desiredFab.x - offX) + 'px';
  fab.style.top = (desiredFab.y - offY) + 'px';
}

/**
 * ★ 面板 / 浮窗：明确宽高为视口内的目标尺寸，位置先贴 0,0 再实测反推偏移。
 *   - float 模式：居中浮窗（宽高按 94vw / 76vh 计算）
 *   - panel 模式：右下角小面板（用期望视口坐标 desiredPanel）
 */
function placeRoot() {
  const doc = hostDoc();
  const root = doc.getElementById('ph-root');
  if (!root || !root.isConnected) return;
  const mode = root.dataset.mode;
  if (mode !== 'float' && mode !== 'panel') return;
  const { w, h } = hostViewport();

  let targetW, targetH, targetX, targetY;
  if (mode === 'float') {
    targetW = Math.min(560, Math.max(180, w - 24), w);
    targetH = Math.min(760, Math.max(320, h * 0.86), Math.max(180, h - 24), h);
    targetX = Math.max(0, Math.round((w - targetW) / 2));
    targetY = Math.max(0, Math.round((h - targetH) / 2));
  } else {
    /* panel 模式：优先用用户调整后的尺寸，否则按默认（344x620，受限时按视口收缩） */
    const defW = Math.min(344, Math.max(240, w - 36));
    const defH = Math.min(620, Math.max(240, h - 186));
    const minW = 180, minH = 180;
    const maxW = Math.max(minW, w - 8);
    const maxH = Math.max(minH, h - 8);
    if (!desiredPanelSize) desiredPanelSize = readPanelSize();
    let sizeW = desiredPanelSize ? desiredPanelSize.w : defW;
    let sizeH = desiredPanelSize ? desiredPanelSize.h : defH;
    sizeW = clamp(sizeW, minW, maxW);
    sizeH = clamp(sizeH, minH, maxH);
    desiredPanelSize = { w: sizeW, h: sizeH };
    targetW = sizeW;
    targetH = sizeH;
    if (!desiredPanel) {
      desiredPanel = readViewportPos(POS_PANEL_KEY) || null;
    }
    if (desiredPanel) {
      targetX = clamp(desiredPanel.x, 4, Math.max(4, w - targetW - 4));
      targetY = clamp(desiredPanel.y, 4, Math.max(4, h - targetH - 4));
      desiredPanel = { x: targetX, y: targetY };
    } else {
      targetX = Math.max(4, w - targetW - 18);
      targetY = Math.max(4, h - targetH - 170);
      desiredPanel = { x: targetX, y: targetY };
    }
  }

  /* 关键：不用 right/bottom/inset 撑满祖先——明确指定宽高与 left/top 基线。
     否则祖先是几千像素高的容器时，测量得到的偏移会把面板丢到屏幕外。 */
  root.style.position = 'fixed';
  root.style.left = '0px';
  root.style.top = '0px';
  root.style.right = 'auto';
  root.style.bottom = 'auto';
  root.style.width = targetW + 'px';
  root.style.height = targetH + 'px';
  root.style.transform = 'none';
  root.style.margin = '0';

  if (!root.classList.contains('on')) return; /* 未打开时不需要测量 */

  /* 强制 reflow，确保上面样式已落到布局 */
  void root.offsetWidth;

  /* 实测实际位置，反推环境偏移（与 pinFab 同思路） */
  const rect = root.getBoundingClientRect();
  const offX = rect.left;
  const offY = rect.top;
  root.style.left = (targetX - offX) + 'px';
  root.style.top = (targetY - offY) + 'px';
}

/** 遮罩：与成就系统 modal 同思路——明确尺寸为视口，反推偏移后铺满可视区 */
function placeMask() {
  const doc = hostDoc();
  const mask = doc.getElementById('ph-mask');
  if (!mask || !mask.classList.contains('on')) return;
  const { w, h } = hostViewport();
  mask.style.position = 'fixed';
  mask.style.top = '0';
  mask.style.left = '0';
  mask.style.right = 'auto';
  mask.style.bottom = 'auto';
  mask.style.margin = '0';
  mask.style.width = w + 'px';
  mask.style.height = h + 'px';
  mask.style.transform = 'none';
  void mask.offsetWidth;
  const rect = mask.getBoundingClientRect();
  if (Math.abs(rect.left) > 0.5) mask.style.left = (-rect.left) + 'px';
  if (Math.abs(rect.top) > 0.5) mask.style.top = (-rect.top) + 'px';
}

let repinBound = false;
function queueRepin() {
  if (repinQueued) return;
  repinQueued = true;
  requestAnimationFrame(() => {
    repinQueued = false;
    pinFab();
    placeRoot();
    placeMask();
  });
}
function bindRepin() {
  if (repinBound) return;
  try {
    const w = hostWin();
    w.addEventListener('scroll', queueRepin, { capture: true, passive: true });
    w.addEventListener('resize', queueRepin);
    w.visualViewport?.addEventListener('resize', queueRepin);
    w.visualViewport?.addEventListener('scroll', queueRepin, { passive: true });
    repinBound = true;
  } catch (e) {}
}

/** 重置悬浮球 / 面板位置（与成就系统的「重置位置」对应） */
function resetPhonePos() {
  try { hostWin().localStorage.removeItem(POS_FAB_KEY); } catch (e) {}
  try { hostWin().localStorage.removeItem(POS_PANEL_KEY); } catch (e) {}
  try { hostWin().localStorage.removeItem(POS_PANEL_SIZE_KEY); } catch (e) {}
  desiredFab = null;
  desiredPanel = null;
  desiredPanelSize = null;   /* ★ 一并恢复默认尺寸 */
  pinFab();
  placeRoot();
  placeMask();
}

/* ============================== 读写变量 ============================== */
function targetMessageId() {
  try {
    const last = typeof getLastMessageId === 'function' ? getLastMessageId() : 'latest';
    if (typeof getChatMessages === 'function') {
      const ms = getChatMessages('0-' + last, { role: 'assistant' });
      if (ms && ms.length) return ms[ms.length - 1].message_id;
    }
    return last;
  } catch (e) { return 'latest'; }
}
function readStat() {
  try {
    if (typeof Mvu === 'undefined' || !Mvu || typeof Mvu.getMvuData !== 'function') return {};
    const tries = [
      { type: 'message', message_id: targetMessageId() },
