/** mutate 返回 { ok, msg }；ok === false 则中止写回 */
async function commitStat(mutate) {
  const token = phoneChatToken();
  if (!samePhoneChat(token)) return false;
  if (typeof Mvu === 'undefined' || !Mvu || typeof Mvu.replaceMvuData !== 'function') {
    toast('当前环境无法写回变量'); return false;
  }
  try {
    const target = targetMessageId();
    const full = Mvu.getMvuData({ type: 'message', message_id: target });
    if (!full || !full.stat_data) { toast('没有可写回的变量'); return false; }
    const res = mutate(full.stat_data) || {};
    if (res.ok === false) { toast(res.msg || '写回已中止'); return false; }
    await Mvu.replaceMvuData(full, { type: 'message', message_id: target });
    if (!samePhoneChat(token)) return false;
    // 主动触发变量更新事件，让 MVU 前端（状态栏「交易」页 / 资金持仓）立即重绘，不等下一轮
    try {
      const ev = (Mvu.events && Mvu.events.VARIABLE_UPDATE_ENDED) || 'mag_variable_update_ended';
      if (typeof eventEmit === 'function') await eventEmit(ev);
    } catch (e) {}
    renderAll();
