function loadStore() {
  let v = {};
  try { if (typeof getVariables === 'function') v = obj(getVariables(SCRIPT_OPT)[VAR_ROOT]); } catch (e) { console.warn('[小手机] 读脚本变量失败', e); }
  const d = defaultSettings();
  const out = Object.assign({}, d, v);
  out.forum = Object.assign({}, d.forum, obj(v.forum));
  out.chat = Object.assign({}, d.chat, obj(v.chat));
  out.stock = Object.assign({}, d.stock, obj(v.stock));
  out.stock.log = arr(obj(v.stock).log);
  out.net = Object.assign({}, d.net, obj(v.net));
  out.byChat = Object.assign(Object.create(null), obj(v.byChat));
  const id = currentPhoneChatId();
  activePhoneChatId = id;
  phoneChatEpoch += 1;
  // A missing ID never shares a fallback bucket or consumes legacy migration.
  if (id !== null) {
    if (out.chatBucketVersion !== 1) {
      if (!Object.prototype.hasOwnProperty.call(out.byChat, id)) out.byChat[id] = phoneBucket(v);
      out.chatBucketVersion = 1;
      out.legacyChatMigratedTo = id;
    }
    if (!Object.prototype.hasOwnProperty.call(out.byChat, id)) out.byChat[id] = emptyPhoneBucket();
    out.byChat[id] = phoneBucket(out.byChat[id]);
  }
  const bucket = id === null ? emptyPhoneBucket() : out.byChat[id];
  // Non-enumerable aliases keep existing UI operations bound to this bucket.
  for (const key of CHAT_FIELDS) {
    delete out[key];
    Object.defineProperty(out, key, { configurable: true, enumerable: false,
      get() { return bucket[key]; }, set(value) { bucket[key] = key === 'deleted' ? arr(value) : obj(value); } });
  }
  if (out.launch !== 'panel') out.launch = 'float';
  // Persist migration immediately, not only after a subsequent user action.
  if (id !== null && typeof replaceVariables === 'function' && typeof getVariables === 'function') {
    const all = obj(getVariables(SCRIPT_OPT));
    all[VAR_ROOT] = Object.assign({}, out);
    replaceVariables(all, SCRIPT_OPT);
  }
  return out;
}
function saveStore() {
  try {
    if (typeof getVariables !== 'function' || typeof replaceVariables !== 'function') return false;
    if (activePhoneChatId !== currentPhoneChatId()) return false;
    const all = obj(getVariables(SCRIPT_OPT));
    const previous = obj(all[VAR_ROOT]);
    const payload = Object.assign({}, STORE);
    payload.byChat = Object.assign(Object.create(null), obj(previous.byChat), obj(STORE.byChat));
    // Before a real chat ID is available, retain flat legacy data untouched.
    if (activePhoneChatId === null && previous.chatBucketVersion !== 1) {
      for (const key of CHAT_FIELDS) if (Object.prototype.hasOwnProperty.call(previous, key)) payload[key] = previous[key];
    }
    all[VAR_ROOT] = payload;
    replaceVariables(all, SCRIPT_OPT);
    return true;
  } catch (e) { console.error('[小手机] 存脚本变量失败', e); toast('设置保存失败'); return false; }
}

