/**
 * 小手机是独立后台任务，不能走会广播 GENERATION_AFTER_COMMANDS 的 TH generateRaw。
 * ST 1.19.0 的 ChatCompletionService 继承连接参数并走同源后端，不启动正文生成流程。
 */
async function callPhoneBackend(cfg, prompts) {
  const st = hostWin().SillyTavern;
  const ctx = st && typeof st.getContext === 'function' ? st.getContext() : null;
  const service = ctx && ctx.ChatCompletionService;
  if (!service || typeof service.presetToGeneratePayload !== 'function' ||
      typeof service.sendRequest !== 'function' || typeof ctx.getChatCompletionModel !== 'function' ||
      !ctx.chatCompletionSettings) {
    throw new Error('当前酒馆缺少独立后台请求接口，请使用兼容的 SillyTavern 版本');
  }

  const custom = !!cfg.apiurl;
  if (!custom && ctx.mainApi !== 'openai') {
    throw new Error('与插头相同模式需要酒馆的聊天补全连接');
  }
  const source = custom ? String(cfg.source || 'openai') : ctx.chatCompletionSettings.chat_completion_source;
  const modelSettings = Object.assign({}, ctx.chatCompletionSettings, { chat_completion_source: source });
  const model = custom && cfg.model ? cfg.model : ctx.getChatCompletionModel(modelSettings);
  const preset = custom ? {
    chat_completion_source: source,
    temperature: num(cfg.temperature, 0.9),
    openai_max_tokens: num(cfg.max_tokens, 512),
  } : {};
  const overrides = { model, messages: prompts, stream: false };
  if (custom) {
    const base = String(cfg.apiurl).trim().replace(/\/+$/, '');
    overrides.reverse_proxy = base;
    overrides.proxy_password = cfg.key || '';
    if (source === 'custom') {
      overrides.custom_url = base;
      // JSON 也是合法 YAML；为这次自定义连接提供自己的鉴权，不改动插头配置。
      overrides.custom_include_headers = cfg.key ? JSON.stringify({ Authorization: 'Bearer ' + cfg.key }) : '';
    }
  }

  // 此接口内部复制当前配置，只构造本次请求，不切换模型或改写全局设置。
  const payload = await service.presetToGeneratePayload(preset, {}, overrides);
  payload.type = 'quiet';
  payload.stream = false;
  const out = await service.sendRequest(payload, true);
  return String(out && out.content || '').trim();
}

async function callLLM(cfg, system, history, userText) {
  const token = phoneChatToken();
  requirePhoneChat(token);
  const result = await callPhoneLLMRaw(cfg, system, history, userText);
  requirePhoneChat(token);
  return result;
}
async function callPhoneLLMRaw(cfg, system, history, userText) {
  const prompts = [{ role: 'system', content: String(system || '') }];
  arr(history).slice(-24).forEach(m => {
    prompts.push({ role: m.dir === 'in' ? 'assistant' : 'user', content: String(m.text || '') });
  });
  prompts.push({ role: 'user', content: String(userText || '（继续）') });

  if (cfg.mode !== 'api') {
    try {
      return await callPhoneBackend(cfg, prompts);
    } catch (e) {
      console.warn('[小手机] 独立后台请求失败');
      toast('ST 后台生成失败：' + (e && e.message ? e.message : e));
      // 不回退 generateRaw，也不在结果不明时自动再发一次直连请求。
      return '';
    }
  }

  if (!cfg.apiurl) { toast('未配置 API 地址，无法生成'); return ''; }
  const base = String(cfg.apiurl).replace(/\/+$/, '');
  const url = /\/chat\/completions$/.test(base) ? base : base + '/chat/completions';
  try {
    const res = await fetch(url, {
      method: 'POST',
      headers: Object.assign({ 'Content-Type': 'application/json' }, cfg.key ? { Authorization: 'Bearer ' + cfg.key } : {}),
      body: JSON.stringify({ model: cfg.model || '', messages: prompts, temperature: num(cfg.temperature, 0.9), max_tokens: num(cfg.max_tokens, 512) }),
    });
    if (!res.ok) throw new Error('HTTP ' + res.status + ' ' + (await res.text()).slice(0, 150));
    const data = await res.json();
    const c0 = data && data.choices && data.choices[0];
    const text = (c0 && (c0.message ? c0.message.content : c0.text)) || '';
    return String(text).trim();
  } catch (e) {
    console.error('[小手机] 直连失败', e);
    toast('生成失败：' + (e && e.message ? e.message : e));
    return '';
  }
}

