}
function appendComment(old, name, text) {
  const cur = Array.isArray(old) ? old.join('｜') : String(val(old, ''));
  const seg = String(name || '匿名') + '：' + String(text || '');
  return cur ? cur + '｜' + seg : seg;
}
function parseReplyLines(text) {
  return String(text || '')
    .split(/\r?\n/)
    .map(s => s.replace(/^[\s>\-*·•\d.、)）]+/, '').trim())
    .filter(Boolean)
    .map(s => {
      const m = s.match(/^(.{1,24}?)[：:]\s*(.+)$/);
      return m ? { name: m[1].trim(), text: m[2].trim() } : { name: '', text: s };
    })
    .slice(0, 6);
}
