/** 仙网生成核心：给指定栏目造 1~2 条内容，并入「互联网」。返回写入条数（0 = 没刷出来）。 */
async function genNetKind(kind) {
  const w = statWorld();
  const exist = Object.keys(statPosts()).map(k => String(val(obj(statPosts()[k]).标题, k)));
  const sys = DEFAULT_NET_PROMPT;
  const user = [
    '【世界】' + val(w.当前篇章, '地球篇') + '｜' + val(w.当前时间, worldTime()) + '｜' + val(w.当前地点, '未知')
      + '｜界域 ' + val(w.当前界域, '地球') + '｜危机 ' + val(w.危机程度, '无'),
    '【已有标题（不得重复）】' + (exist.length ? exist.join('；') : '（无）'),
    (STORE.forum.includeChat ? '【当前正文（供贴合剧情造内容，仍不得围绕主角、不得泄密）】\n' + recentChatText(2, 800) : ''),
    '【本次要求】类型固定为「' + kind + '」，生成 1~2 条，每条带 2~4 条评论。',
    '只输出 JSON。',
  ].filter(Boolean).join('\n');
  const text = await callLLM(STORE.forum, sys, [], user);
  if (!text) return 0;
  let o = null;
  const m = String(text).replace(/```[a-z]*\s*/gi, '').match(/\{[\s\S]*\}/);
  try { o = JSON.parse(m ? m[0] : text); } catch (e) { o = null; }
  if (!o) { toast('AI 返回的不是合法 JSON'); return 0; }
  const list = arr(o.帖子).slice(0, 3);
  if (!list.length) { toast('AI 没有产出内容'); return 0; }
  const used = [];
  const ok = await commitStat(st => {
    const box = obj(st.互联网);
    list.forEach(o2 => {
      const t = String(obj(o2).标题 || '').trim().slice(0, 30);
      if (!t || used.includes(t) || exist.includes(t)) return;      // 同批/已有标题都不重复
      used.push(t);
      box[t + '·' + uid().slice(-4)] = {
        类型: kind,
        平台: String(obj(o2).平台 || '网络'),
        标题: t,
        来源: String(obj(o2).来源 || '匿名'),
        时间: String(obj(o2).时间 || worldTime()),
        地点: String(obj(o2).地点 || ''),
        标签: String(obj(o2).标签 || ''),
        热度: num(obj(o2).热度, 0),
        可信度: kind === '风闻' ? clamp100(obj(o2).可信度) : 0,
        内容: String(obj(o2).内容 || ''),
        评论: String(obj(o2).评论 || ''),
      };
    });
    if (!used.length) return { ok: false, msg: '没有可写入的新标题（可能都重复了）' };
    return { ok: true, msg: '仙网更新 ' + used.length + ' 条' };
  });
  return ok ? used.length : 0;
}
