/* ================== 聊天记录（读取当前酒馆的正文对话） ================== */
/**
 * 卡内约定的对话标记：[说|说话人|情绪|内容]（与「对话美化」正则同款）
 * 剧情时间取自正文里的 <bbs_start>2024/5/28 09:55</bbs_start>
 */
const CHAT_SAY_RE = /\[说\|([^|\]]{1,24})\|([^|\]]{0,12})\|([^|\]]+)\]/g;
const CHAT_TIME_RE = /<bbs_start>\s*([^<\n]{1,40}?)\s*<\/bbs_start>/;
/** 示例文本里的占位名 / 占位情绪，必须过滤（否则通讯录里会冒出「角色名」「情绪」这种假人） */
const LOG_PLACE = ['角色名', '角色', '姓名', '名字', '人名', 'NPC', 'npc', '某人', '人物', '旁白', '系统',
  '主角', '我', '你', '他', '她', '对方', '情绪', '情绪名', '表情', 'xx', 'XX'];
/** 情绪 → 色调，与卡内 .csmg-say 的 data-type 配色保持一致 */
const MOOD_TONE = {
  微笑: 'gold', 开心: 'gold', 喜欢: 'gold', 害羞: 'pink', 凝重: 'blue',
  生气: 'red', 战斗: 'red', 悲伤: 'blue', 受伤: 'blue',
  惊讶: 'lime', 厌恶: 'green', 迷糊: 'purple',
};
const moodTone = m => MOOD_TONE[String(m || '').trim()] || '';
const logText = t => String(t || '').replace(/\s*\n+\s*/g, ' ').trim();

let logCache = { key: '', rows: [], names: [], floors: 0 };
let logByName = null;
const chatLogOpt = () => {
  const c = obj(STORE.chat);
  return { on: c.readLog !== false, depth: clamp(num(c.logDepth, 60), 0, 400) };
};

/** 扫描最近 N 层助手正文，抽出 [说|…] 发言；按「楼层范围」缓存，聊天记录不变时不重扫 */
function scanChatLog(force) {
  const { on, depth } = chatLogOpt();
  const off = { rows: [], names: [], floors: 0, key: 'off' };
  if (!on || !depth) return off;
  let last = -1;
  try {
    if (typeof getChatMessages !== 'function') return Object.assign({}, off, { key: 'noapi' });
    last = num(typeof getLastMessageId === 'function' ? getLastMessageId() : -1, -1);
  } catch (e) { return Object.assign({}, off, { key: 'err' }); }
  if (last < 0) return Object.assign({}, off, { key: 'nomsg' });
  const start = Math.max(0, last - depth + 1);
  const key = String(activePhoneChatId) + '|' + phoneChatEpoch + '|' + start + '-' + last;
  if (!force && logCache.key === key) return logCache;
  try {
    const msgs = getChatMessages(start + '-' + last, { role: 'assistant' });
    const hero = heroName();
    const rows2 = [], names = new Set();
    let floors = 0;
    arr(msgs).forEach(m => {
      const d = obj(m), text = String(val(d.message, ''));
      if (!text) return;
      const tm = text.match(CHAT_TIME_RE);
      const t = tm ? tm[1] : '';
      let hit = false;
      CHAT_SAY_RE.lastIndex = 0;
      let x;
      while ((x = CHAT_SAY_RE.exec(text))) {
        const who = String(x[1] || '').trim();
        const mood = String(x[2] || '').trim();
        const body = logText(x[3]);
        if (!who || !body) continue;
        if (LOG_PLACE.indexOf(who) >= 0 || LOG_PLACE.indexOf(mood) >= 0) continue;
        if (hero && who === hero) continue;
        rows2.push({ floor: num(d.message_id, 0), who, mood, t, text: body });
        names.add(who);
        hit = true;
      }
      if (hit) floors++;
    });
    logCache = { key, rows: rows2, names: Array.from(names), floors };
    return logCache;
  } catch (e) {
    console.warn('[小手机] 读聊天记录失败', e);
    return Object.assign({}, off, { key: 'err' });
  }
}
/** 某人在剧情里说过的话（按说话人分桶缓存）
 *  注意：判断缓存是否过期要比「缓存对象本身」，不能只比 key ——
 *  同一楼层范围被强制重扫（换 swipe 页 / 点重新读取）时 key 不变，
 *  只看 key 会一直用旧分桶，表现为「点了重新读取没反应」。 */
function logRowsOf(name) {
  const c = scanChatLog();
  if (!logByName || logByName.src !== c) {
    const m = new Map();
    c.rows.forEach(r => { if (!m.has(r.who)) m.set(r.who, []); m.get(r.who).push(r); });
    logByName = { src: c, map: m };
  }
  return logByName.map.get(name) || [];
}
const logCount = () => scanChatLog().rows.length;
/** 取最近 N 层正文原文（供「传入正文」开关用），按字符数截断 */
let storyCache = { key: '', txt: '' };
const resetStoryCache = () => { storyCache = { key: '', txt: '' }; };

/** 去掉正文里的机器块（变量更新 / 解析 / 战斗思考），只留给人看的故事内容 */
function cleanStoryText(t) {
  return String(t || '')
    .replace(/<UpdateVariable>[\s\S]*?<\/UpdateVariable>/gi, '')
    .replace(/<JSONPatch>[\s\S]*?<\/JSONPatch>/gi, '')
    .replace(/<Analysis>[\s\S]*?<\/Analysis>/gi, '')
    .replace(/<BattleCOT>[\s\S]*?<\/BattleCOT>/gi, '')
    .replace(/<StatusPlanned>[\s\S]*?<\/StatusPlanned>/gi, '')
    .replace(/```[\s\S]*?```/g, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const sliceText = (t, maxLen) => {
  const L = num(maxLen, 0);
  return (L > 0 && t.length > L) ? t.slice(0, L) + '……（后略）' : t;
};

/** 取最近 n 层正文原文（已去机器块，带缓存）。maxLen <= 0 表示不限 */
function recentChatText(n = 2, maxLen = 800, force) {
  try {
    if (typeof getChatMessages !== 'function') return '';
    const last = num(typeof getLastMessageId === 'function' ? getLastMessageId() : -1, -1);
    if (last < 0) return '';
    const floors = Math.max(1, num(n, 2));
    const start = Math.max(0, last - floors + 1);
    const key = start + '-' + last;
    if (!force && storyCache.key === key) return sliceText(storyCache.txt, maxLen);
    const msgs = getChatMessages(start + '-' + last, { role: 'assistant' });
    const txt = cleanStoryText(arr(msgs).map(m => String(val(obj(m).message, ''))).filter(Boolean).join('\n'));
    storyCache = { key: key, txt: txt };
    return sliceText(txt, maxLen);
  } catch (e) { return ''; }
}

/** 传讯用的正文原文：按设置取最近若干层、截断到字数上限 */
function storyTextForChat() {
  if (STORE.chat.includeText === false) return '';
  return recentChatText(num(obj(STORE.chat).textFloors, 3), num(obj(STORE.chat).textLen, 2000));
}

/* ============================== 世界书：人物设定 ============================== */
/* 传讯要写出「这个角色才会说的话」，光靠变量里的档案字段不够 —— 性格底色、身世、
   说话习惯都写在世界书的「人物详细:XXX」这类条目里。这里把当前生效的世界书抓进来，
   按联系人名字匹配相关条目，作为【世界书人物设定】一起交给 AI。           */
let loreCache = { at: 0, key: '', list: [] };
const LORE_TTL = 5 * 60 * 1000;
const resetLoreCache = () => { loreCache = { at: 0, key: '', list: [] }; };

/** MVU 与初始化那类机器条目不该进提示词 */
const LORE_SKIP = /^(📦|🧭|🌍|🧬|👤|🎬|🌐|\[mvu|\[initvar|变量列表|📜)/;

function loreBookNames() {
  const out = [];
  try { if (typeof getChatWorldbookName === 'function') { const n = getChatWorldbookName('current'); if (n) out.push(n); } } catch (e) { }
  try {
    if (typeof getCharWorldbookNames === 'function') {
      const c = getCharWorldbookNames('current') || {};
      if (c.primary) out.push(c.primary);
      arr(c.additional).forEach(x => { if (x) out.push(x); });
    }
  } catch (e) { }
  try { if (typeof getGlobalWorldbookNames === 'function') arr(getGlobalWorldbookNames()).forEach(x => { if (x) out.push(x); }); } catch (e) { }
  return Array.from(new Set(out.filter(Boolean))).slice(0, 8);
}

/** 载入（首次或过期时）当前所有生效世界书的条目，去重后缓存 */
async function ensureLore(force) {
  const loreToken = phoneChatToken();
  const names = loreBookNames();
  const key = names.join('|');
  if (!force && loreCache.key === key && loreCache.list.length && (Date.now() - loreCache.at) < LORE_TTL) return loreCache.list;
  if (typeof getWorldbook !== 'function') return loreCache.list;
  const raw = [];
  for (const n of names) {
    try {
      arr(await getWorldbook(n)).forEach(e => {
        const o = obj(e);
        const nm = String(val(o.name, val(o.comment, '')));
        const ct = String(val(o.content, ''));
        if (!nm || !ct || o.enabled === false) return;
        const st = obj(o.strategy);
        const ks = arr(st.keys && st.keys.length ? st.keys : o.keys).map(k => String(k));
        raw.push({ name: nm, content: ct, keys: ks });
      });
    } catch (err) { /* 单个世界书读不到就跳过 */ }
  }
  const map = new Map();
  raw.forEach(e => { const p = map.get(e.name); if (!p || e.content.length > p.content.length) map.set(e.name, e); });
  if (!samePhoneChat(loreToken)) return [];
  loreCache = { at: Date.now(), key: key, list: Array.from(map.values()) };
  return loreCache.list;
}

/** 去掉条目正文首尾的 /角色名 与 角色名/ 分隔符，读起来干净些 */
function cleanLoreText(t, name) {
  let out = String(t || '');
  if (name) {
    out = out.split('\n').filter(ln => {
      const x = ln.trim();
      return x !== '/' + name && x !== name + '/';
    }).join('\n');
  }
  return out.replace(/\n{3,}/g, '\n\n').trim();
}

/** 同步取某联系人的世界书设定（依赖 ensureLore 已跑过） */
function loreForContact(name) {
  if (!name || STORE.chat.includeLore === false) return [];
  const all = loreCache.list || [];
  if (!all.length) return [];
  const nm = String(name);
  const extraNames = String(val(obj(STORE.chat).loreExtra, '')).split(/[,，、\n]/).map(x => String(x).trim()).filter(Boolean);
  const hit = [], extra = [], seen = new Set();
  all.forEach(e => {
    if (LORE_SKIP.test(e.name)) return;
    if (extraNames.some(x => x && e.name.indexOf(x) >= 0)) { extra.push(e); return; }
    const inName = e.name === nm || e.name.indexOf(nm) >= 0;
    const inKeys = e.keys.some(k => k && k.indexOf(nm) >= 0);
    const inBody = e.content.indexOf('/' + nm) >= 0 || e.content.indexOf(nm) >= 0;
    if (inName || inKeys || inBody) hit.push({ e: e, sc: (inName ? 4 : 0) + (inKeys ? 3 : 0) + (inBody ? 1 : 0) });
  });
  hit.sort((a, b) => b.sc - a.sc);
  const max = Math.max(1, num(obj(STORE.chat).loreMax, 2));
  const len = num(obj(STORE.chat).loreLen, 900);
  const out = [];
  hit.slice(0, max).map(x => x.e).concat(extra.slice(0, 4)).forEach(e => {
    if (seen.has(e.name)) return;
    seen.add(e.name);
    out.push({ name: e.name, text: sliceText(cleanLoreText(e.content, nm), len) });
  });
  return out;
}

