  if (!root) throw new Error('没填图床根地址');
  try {
    const r = await fetch(root + '/assets/manifest.json', { cache: 'no-cache' });
    if (!r.ok) throw new Error('Manifest ' + r.status);
    const m = obj(await r.json());
    return { paths: Array.isArray(m.paths) ? m.paths : [], aliases: m.aliases };
  } catch (e1) {
    const hm = avHostMeta();
    if (!hm) throw e1;
    const r = await fetch('https://api.github.com/repos/' + hm.owner + '/' + hm.repo + '/git/trees/' + encodeURIComponent(hm.branch) + '?recursive=1',
      { headers: { Accept: 'application/vnd.github+json' } });
    if (!r.ok) throw new Error('GitHub ' + r.status);
