/** 先上缓存（状态栏那份优先），再后台拉最新；索引变了就重绘 */
async function loadAssets(force) {
  if (avLoading) return avLoading;
  if (avIdx.ready && !force) return null;
  avLoading = (async () => {
    if (!avCfg().show) return;
    if (!force) {
      const cached = avReadCache(AV_SHARED_CACHE_KEY) || avReadCache(AV_CACHE_KEY);
      if (cached) {
        if (avApplyIndex(cached.paths, cached.aliases)) { try { renderAll(); } catch (e) {} }
        avIdx.from = '缓存';
      }
    }
    try {
      const fresh = await avFetchIndex();
      const isNew = String(fresh.paths.length) !== String(avIdx.stamp.split('|')[0]) || !avIdx.ready;
      if (avApplyIndex(fresh.paths, fresh.aliases) || isNew) { avIdx.from = '在线'; try { renderAll(); } catch (e) {} }
      try { hostWin().localStorage.setItem(AV_CACHE_KEY, JSON.stringify(fresh)); } catch (e) {}
    } catch (e) {
      console.warn('[小手机] 图床索引读取失败', e && e.message ? e.message : e);
      avIdx.from = avIdx.ready ? '缓存' : '读取失败';
      try { renderAll(); } catch (err) {}
