  const tomb = new Set(arr(STORE.deleted));
  if (tomb.has('@' + name)) return;   // 整个联系人已删过，不再从「讯息」导回
  const seen = new Set(local.map(m => m.dir + '|' + m.text));
  const hn = heroName();
  rows(statMessages()).forEach(([k, m]) => {
    const d = obj(m);
    const sender = String(val(d.发送者, ''));
    const text = String(val(d.内容, ''));
    if (!text) return;
    const to = String(val(d.收件人, ''));
    let dir = '';
    if (sender === name) {
      if (to && to !== hn) return;          // v1.9.3：明确发给别人的消息不进本会话
      dir = 'in';
    } else if (sender === hn) {
      if (to) { if (to !== name) return; }  // v1.9.3：主角发出的消息按「收件人」归属
      else if (String(k).indexOf('我→' + name + '·') !== 0) return;   // 旧数据靠键名归属；归不了属的不再每个会话都塞
      dir = 'out';
    } else return;
    if (tomb.has(sender + '|' + text)) return;   // 已删的消息不导回
    const sig = dir + '|' + text;
    if (seen.has(sig)) return;
    seen.add(sig);
    local.push({ dir, t: String(val(d.时间, '')), text });
  });
