function writeMessagesToStat(entries) {
  if (STORE.writeToStat === 'off' || !entries.length) return Promise.resolve();
  const list = entries.filter(e => STORE.writeToStat === 'both' || e.dir === 'in');
  if (!list.length) return Promise.resolve();
  return commitStat(st => {
    const box = obj(st.讯息);
    const base = Date.now().toString(36) + Math.random().toString(36).slice(2, 5);   // 加随机后缀，避免同毫秒两次写回撞名
    list.forEach((e, i) => {
      const key = (e.dir === 'in' ? e.name + '·' : '我→' + e.name + '·') + base + i;
      box[key] = { 发送者: e.dir === 'in' ? e.name : heroName(), 收件人: e.dir === 'in' ? heroName() : e.name, 时间: worldTime(), 内容: e.text };
    });
    return { ok: true };
  });
}
async function sendToContact(name, text) {
  const token = phoneChatToken(); requirePhoneChat(token);
  const t = String(text || '').trim();
  if (!t) return;
  pushThread(name, 'out', t);
  renderAll();
  await writeMessagesToStat([{ dir: 'out', name, text: t }]);
  requirePhoneChat(token);
  if (!STORE.chat.enabled) { toast('已发送（通讯 AI 未启用）'); return; }
  await ensureLore();
  requirePhoneChat(token);
  const ctx = buildChatContext(name);   // 世界 / 主角 / 档案 / 手机往来 / 剧情发言 / 最近正文原文
  const raw = await callLLM(STORE.chat, STORE.chat.system, threadOf(name).slice(-12),
    ctx ? (ctx + '\n\n（请据以上内容继续对话）') : '（继续对话）');
  const lines = String(raw || '').split(/\r?\n/).map(s => s.trim()).filter(Boolean).slice(0, 3);
  if (!lines.length) { toast('对方没有回复'); return; }
  lines.forEach(line => pushThread(name, 'in', line));
  if (uiGet().chatWith === name) clearUnread(name); else bumpUnread(name, lines.length);
  renderAll();
  await writeMessagesToStat(lines.map(line => ({ dir: 'in', name, text: line })));
}

