    slowRamp = Math.min(1, age / 260), midRamp = Math.min(1, age / 40),
    trend = mkNoise(seed, day / 61) * s.幅 * 24 * slowRamp + mkNoise(seed ^ 0x1234, day / 13) * s.幅 * 9 * midRamp,
    daily = (mkRnd(seed ^ (day * 2654435761)) * 2 - 1) * s.幅,
