  const tens = rows(w.世界局势).map(([, d]) => clamp100(obj(d).紧张度));
  const avg = tens.length ? tens.reduce((a, b) => a + b, 0) / tens.length : 0;
  return { lv: lv, tension: Math.round(avg), drift: -(lv * .035) - (avg / 100) * .02 };
}
function newsFeed() {
  const w = statWorld(), out = [];
  const push = (src, title, d) => {
    const o = obj(d);
    const text = [title, o.描述, o.内容, o.标题, o.摘要, o.影响, o.行动, o.全球影响, o.评论].filter(Boolean).join(' ');
    if (text) out.push({ src: src, title: String(o.标题 || title), text: text, 全球: src === '全球' || src === '局势' });
  };
  rows(w.动向).forEach(([t, d]) => push('本地', t, d));
  rows(w.政府动向).forEach(([t, d]) => push('政府', t, d));
  rows(w.军事动向).forEach(([t, d]) => push('军事', t, d));
  rows(w.国家动向).forEach(([t, d]) => push('国家', t, d));
  rows(w.全球动向).forEach(([t, d]) => push('全球', t, d));
  rows(w.世界局势).forEach(([t, d]) => push('局势', t, d));
  rows(readStat().互联网).forEach(([t, d]) => push('网络', t, d));
