const mkTone = text => { let s = 0; MK_GOOD.forEach(k => { if (text.includes(k)) s++; }); MK_BAD.forEach(k => { if (text.includes(k)) s--; }); return Math.max(-3, Math.min(3, s)); };
/** 股票池 = 内置 MARKET + 玩家势力里的「企业」 */
function mkRoster() {
