    .filter(([n, d]) => String(obj(d).类型) === '企业' && !MARKET.some(s => s.名 === n))
    .map(([n]) => { const h = mkHash(n); return { 市: 'a', 码: ('00' + h % 1000000).slice(-6), 名: n, 板: '综合', 基: 6 + h % 3500 / 100, 幅: .036, 词: [n], 自: true }; });
  return MARKET.concat(extra);
