/** 全量行情（含停牌/退市/未上市标记与涨跌幅） */
function quoteAll(clock) {
  const stat = readStat(), mood = marketMood(), feed = newsFeed(), prevDay = mkPrevDay(clock.day), dead = {};
  rows(stat.所处势力).forEach(([n, d]) => { if (MK_DEAD.test(String(val(obj(d).势力状态, '')))) dead[n] = true; });
  return mkRoster().map(s => {
    const v = MK_VENUES[s.市], listed = s.上市 ? mkDayFromISO(s.上市) : -99999,
      news = feed.filter(f => [s.名].concat(s.词 || []).some(k => k && f.text.includes(k))).map(f => Object.assign({}, f, { tone: mkTone(f.text) })),
      hit = news.map(n => n.text).join(' '),
      tone = news.reduce((a, n) => a + n.tone, 0),
      localWeight = v.本地 ? 1 : .3,
      macro = (news.some(n => n.全球) || v.本地) ? 1 : .6,
      sector = (MK_BETA[s.板] === undefined ? -.4 : MK_BETA[s.板]) * mood.lv * .03 * localWeight,
      bias = mood.drift * localWeight * macro + sector + Math.max(-.05, Math.min(.05, tone * .016)),
      prev = rawPrice(s, prevDay, 15),
      shock = mkShock(s, clock.day),
      halt = mkHalt(s, clock.day),
      st = v.本地 && prev < s.基 * .35,
      cap = st ? .05 : (v.限 || .18);
