    if (clock.day < listed) flag = { k: '未上市', t: s.上市 + ' 挂牌' };
    else if (dead[s.名] || MK_DEAD.test(hit)) flag = { k: '退市', t: '已摘牌 · 仅可清仓' };
    else if (MK_HALT.test(hit)) flag = { k: '停牌', t: '公告停牌' };
    else if (halt) flag = { k: '停牌', t: '临时核查 · 还剩' + halt.left + '日' };
    let price, chg;
    if (flag && flag.k === '未上市') { price = 0; chg = 0; }
    else if (flag) { price = flag.k === '退市' ? round2(prev * .4) : round2(prev); chg = flag.k === '退市' ? -.6 : 0; }
    else {
      chg = Math.max(-cap, Math.min(cap, rawPrice(s, clock.day, clock.hour) * (1 + bias + (shock ? shock.v : 0)) / prev - 1));
      price = Math.max(.01, round2(prev * (1 + chg)));
    }
    return Object.assign({}, s, {
      venue: v, prev: prev, price: price, chg: chg, news: news, shock: flag ? null : shock,
      flag: flag, st: st, cap: cap, tradable: !flag || flag.k === '退市',
