}
/** 指数 = 该市场个股涨跌的平均 */
function mkIndex(quotes, venue) {
  const list = quotes.filter(q => q.市 === venue && !q.flag);
  if (!list.length) return 0;
  return list.reduce((a, q) => a + q.chg, 0) / list.length;
}

