const nodeOf = v => Array.isArray(v) ? nodeOf(v[0]) : v;
function childObj(parent, key) {
  const cur = parent[key], inner = nodeOf(cur);
  if (inner && typeof inner === 'object' && !Array.isArray(inner)) return inner;
  const fresh = {};
  if (Array.isArray(cur)) cur[0] = fresh; else parent[key] = fresh;
  return fresh;
}
function setLeaf(parent, key, v) { const cur = parent[key]; if (Array.isArray(cur)) cur[0] = v; else parent[key] = v; }
const leafNum = (parent, key) => num(nodeOf(obj(parent)[key]));
const heroAsset = () => obj(statHero().资产);
const purse = () => obj(heroAsset().货币);
const cnyKey = () => Object.keys(purse()).find(k => /人民币|现金|存款|RMB/i.test(k)) || '人民币';
const walletOf = cur => moneyInt(obj(purse()[cur === '人民币' ? cnyKey() : cur]).数量);
const holdBox = () => obj(obj(heroAsset()._股市).持仓);
const realizedPL = () => moneyInt(obj(heroAsset()._股市).累计盈亏);
function cashAccount(ctx, cur) {
  const key = cur === '人民币' ? cnyKey() : cur, acc = childObj(ctx.money, key);
  if (acc.数量 === undefined) acc.数量 = 0;
  if (acc.单位 === undefined) acc.单位 = cur === '美元' ? '美元' : '元';
  if (acc.说明 === undefined) acc.说明 = cur === '美元' ? '境外证券账户' : '证券账户结算';
  return acc;
}
function mkSpend(ctx, cur, amount, day) {
  amount = moneyInt(amount);
  const acc = cashAccount(ctx, cur), bal = moneyInt(nodeOf(acc.数量));
  if (bal >= amount) { setLeaf(acc, '数量', bal - amount); return null; }
  if (cur === '人民币') return '现金不足，还差 ' + moneyTxt(amount - bal) + ' 元';
  const rate = fxRate(day), need = moneyInt((amount - bal) * rate * 1.003), rmb = cashAccount(ctx, '人民币'), rb = moneyInt(nodeOf(rmb.数量));
  if (rb < need) return '美元与人民币都不够，还差约 ' + moneyTxt(need - rb) + ' 元';
  setLeaf(rmb, '数量', rb - need);
  setLeaf(acc, '数量', 0);
  return null;
}
function mkCredit(ctx, cur, amount) { const acc = cashAccount(ctx, cur); setLeaf(acc, '数量', moneyInt(nodeOf(acc.数量)) + moneyInt(amount)); }
function buyingPower(ctx, cur, day) {
  if (cur === '人民币') return moneyInt(nodeOf(cashAccount(ctx, '人民币').数量));
  const usd = moneyInt(nodeOf(cashAccount(ctx, cur).数量));
  const rmb = moneyInt(nodeOf(cashAccount(ctx, '人民币').数量));
  return usd + rmb / (fxRate(day) * 1.003);
}
/** 写回股市节点（与状态栏交易页同一套路径） */
async function commitMarket(mutate) {
  return commitStat(st => {
    const hero = childObj(st, '主角'), asset = childObj(hero, '资产'),
      ctx = { money: childObj(asset, '货币'), desk: childObj(asset, '_股市') };
    ctx.hold = childObj(ctx.desk, '持仓');
    const note = mutate(ctx);
    if (!note) return { ok: false };
    return { ok: true, msg: note };
  });
}
/**
 * 下单核心（手续费/印花税与状态栏一致）。dir: '买入'|'卖出'；lots: 手数，'all' 表示全仓/清仓。
 * 返回 { ok, text }，text 为成交回报或失败原因。
 */
function mkTrade(ctx, dir, name, lots, clock) {
  const quotes = quoteAll(clock);
  const q = quotes.find(s => s.名 === name);
  if (!q) return { ok: false, text: '查无此股：' + name };
  if (dir === '买入' && !q.canBuy) return { ok: false, text: name + ' ' + q.flag.k + '，无法买入' };
  if (dir === '卖出' && !q.canSell) return { ok: false, text: name + ' ' + q.flag.k + '，无法卖出' };
  const cur = q.venue.币, unit = q.venue.手, held = leafNum(obj(ctx.hold)[name], '股数');
  let shares;
  // lots = 'all'，或手数 ≥ 999（AI 提示词里约定的「全仓/清仓」），或没给手数 → 按可用资金/全部持仓
  if (lots === 'all' || num(lots, 0) >= 999 || !(num(lots, 0) > 0)) {
    shares = dir === '买入' ? Math.floor(buyingPower(ctx, cur, clock.day) / (q.price * unit * 1.001)) * unit : held;
  } else shares = num(lots, 0) * unit;
  if (dir === '卖出' && shares > held) shares = Math.floor(held / unit) * unit || held;
  if (!(shares > 0)) return { ok: false, text: dir === '买入' ? (cur + '不足一手') : '没有可卖的股份' };
  const gross = moneyInt(q.price * shares), sym = q.venue.符;
  if (dir === '买入') {
    const fee = Math.max(q.市 === 'a' ? 5 : 1, moneyInt(gross * .0003));
    const err = mkSpend(ctx, cur, gross + fee, clock.day);
    if (err) return { ok: false, text: err };
    const cell = childObj(ctx.hold, name), had = leafNum(cell, '股数'), cost = leafNum(cell, '成本');
    setLeaf(cell, '股数', had + shares);
    setLeaf(cell, '成本', round2((had * cost + gross + fee) / (had + shares)));
    return { ok: true, text: '买入 ' + name + ' ' + shares + ' 股 @ ' + sym + money2(q.price) };
  }
  const cell = nodeOf(ctx.hold[name]), have = cell ? leafNum(cell, '股数') : 0;
  if (have < shares) return { ok: false, text: '持仓不足，只有 ' + have + ' 股' };
  const fee = Math.max(q.市 === 'a' ? 5 : 1, moneyInt(gross * .0003)) + (q.市 === 'a' ? moneyInt(gross * .001) : 0);
  const net = moneyInt(gross - fee), cost = leafNum(cell, '成本');
  mkCredit(ctx, cur, net);
  if (have - shares <= 0) delete ctx.hold[name]; else setLeaf(cell, '股数', have - shares);
  setLeaf(ctx.desk, '累计盈亏', moneyInt(leafNum(ctx.desk, '累计盈亏') + (net - cost * shares) * (cur === '美元' ? fxRate(clock.day) : 1)));
  return { ok: true, text: '卖出 ' + name + ' ' + shares + ' 股 @ ' + sym + money2(q.price) };
}
/** 手动下单（带 toast） */
async function marketOrder(dir, name, lots) {
  const clock = worldClock();
  if (!clock) { toast('此地此时没有股市'); return false; }
  const ok = await commitMarket(ctx => {
    const r = mkTrade(ctx, dir, name, lots, clock);
    return r.ok ? r.text : '';
  });
  if (!ok) toast('下单未成交（资金或持仓不足）');
  return ok;
}

