    '【美股行情】' + (board('us') || '（无）'),
    '【消息面】' + (related.length ? related.map(f => f.text.slice(0, 60)).join(' ／ ') : '（暂无）'),
  ];
  const log = arr(STORE.stock.log).slice(-3);
  if (log.length) lines.push('【最近操盘】' + log.map(l => (l.t || '') + ' ' + String(l.复盘 || l.note || '').slice(0, 40)).join(' ／ '));
  return lines.filter(Boolean).join('\n');
}
function parseTradeJSON(text) {
  let s = String(text || '').replace(/```[a-z]*\s*/gi, '').trim();
  const m = s.match(/\{[\s\S]*\}/);
  if (!m) return null;
  try { return JSON.parse(m[0]); } catch (e) {}
  try { return JSON.parse(m[0].replace(/,\s*([}\]])/g, '$1')); } catch (e) { return null; }
}
/** AI 操盘：生成计划 → 用同一套成交逻辑执行 → 记账 */
async function runAITrade(kind) {
  const clock = worldClock();
  if (!clock) { toast('此地此时没有股市'); return; }
  if (!STORE.stock.enabled) { toast('AI 操盘未启用'); return; }
  const ctxText = tradeContext(clock);
  const text = await callLLM(STORE.stock, STORE.stock.system, [], ctxText + '\n\n请给出这一轮的操盘计划。');
  if (!text) { toast('没有生成到操盘计划'); return; }
  const plan = parseTradeJSON(text);
  if (!plan) { toast('AI 返回的不是合法 JSON'); return; }
  const orders = arr(plan.委托).slice(0, Math.max(1, num(STORE.stock.maxOrders, 3)));
  const deals = [], fails = [];
  const changed = await commitMarket(ctx => {
    orders.forEach(o => {
      const dir = String(obj(o).向 || '').includes('卖') ? '卖出' : '买入';
      const name = String(obj(o).股 || '').trim();
      if (!name) return;
      const r = mkTrade(ctx, dir, name, obj(o).手 === undefined ? 1 : obj(o).手, clock);
      if (r.ok) deals.push(r.text + (obj(o).理由 ? '（' + String(obj(o).理由).slice(0, 40) + '）' : ''));
      else fails.push('✗ ' + r.text);
    });
    if (!deals.length) return '';       // 没成交就不写回变量
    return 'AI 操盘：成交 ' + deals.length + ' 笔' + (fails.length ? '（放弃 ' + fails.length + ' 笔）' : '');
  });
  const entry = {
    t: val(statWorld().当前时间, worldTime()),
    kind: kind === 'auto' ? 'auto' : 'manual',
    复盘: String(plan.复盘 || '').slice(0, 120),
    备注: String(plan.备注 || '').slice(0, 120),
    成交: deals,
    失败: fails,
  };
  STORE.stock.log = arr(STORE.stock.log).concat([entry]).slice(-30);
  saveStore();
  if (changed && STORE.stock.writeToStat && deals.length) {
    await writeMessagesToStat(deals.slice(0, 2).map(t => ({ dir: 'in', name: '临渊证券', text: t })));
  }
  renderAll();
  if (!orders.length) toast('AI 决定按兵不动');
  else if (!deals.length) toast('操盘未成交：' + (fails[0] || '资金或持仓不足'));
  else toast('AI 操盘成交 ' + deals.length + ' 笔');
}
/** 已完成的助手正文楼层数（用 message_id + 文本长度做去重指纹） */
function aiFloorStats() {
  try {
    if (typeof getChatMessages !== 'function') return { count: 0, id: '' };
    const last = typeof getLastMessageId === 'function' ? getLastMessageId() : 0;
    const ms = getChatMessages('0-' + last, { role: 'assistant' });
    if (!ms || !ms.length) return { count: 0, id: '' };
    const m = ms[ms.length - 1];
    return { count: ms.length, id: String(m.message_id) + ':' + String(m.message || '').length };
  } catch (e) { return { count: 0, id: '' }; }
}
function resetTradeCounter() { STORE.stock.lastSeen = ''; STORE.stock.count = 0; saveStore(); }
/** 每来一个 AI 正文楼层记一次；攒够 every 层就自动操盘一次 */
function maybeAutoTrade() {
  if (!STORE.stock.enabled || !STORE.stock.auto) return;
  const s = aiFloorStats();
  if (!s.id || s.id === STORE.stock.lastSeen) return;
  STORE.stock.lastSeen = s.id;
  STORE.stock.count = num(STORE.stock.count, 0) + 1;
  const every = Math.max(1, num(STORE.stock.every, 3));
  const fire = STORE.stock.count >= every;
  if (fire) STORE.stock.count = 0;
  saveStore();
  if (fire) runAITrade('auto');
}

