/* --- 展示层（行情终端风）：只做派生与绘制，不动行情引擎、不改 AI 上下文 --- */
const MK_IDX_NAME = { a: '上证指数', us: '纳斯达克' };
const MK_IDX_BASE = { a: 2213.60, us: 2703.90 };   /* 2012 年量级的指数基准点位 */
/** 指数卡：点位 = 基准点位 ×（1 + 该市场平均涨跌） */
function idxCard(quotes, venue) {
  const chg = mkIndex(quotes, venue), base = MK_IDX_BASE[venue] || 2000, pts = base * (1 + chg);
  const tone = chg > .0005 ? 'up' : (chg < -.0005 ? 'down' : 'flat');
  return `<div class="ph-idx ${tone}"><small>${esc(MK_IDX_NAME[venue] || venue)}</small>` +
    `<b>${pts.toFixed(2)}</b><i>${pts - base >= 0 ? '+' : ''}${(pts - base).toFixed(2)} ${pct(chg)}</i></div>`;
}
/** 当日分时序列（纯绘图用，引擎与 AI 上下文都不受影响）：
    今开 = 昨收 + 跳空缺口（缺口感掉当日涨跌的一小部分，其余在盘中走完）→「振幅」会
    自然随当日涨跌放大，跟真实市场一致；中间用「确定性随机游走」造形态，尺度跟个股的「幅」走；
    末点严格等于当前价，并按已过的交易时段（9:30–15:00）截断。 */
function intradaySeries(q, clock, n) {
  n = n || 30;
  const amp = q.幅 || .03;
  const frac = Math.max(.18, Math.min(1, (clock.hour - 9.5) / 5.5));
  const m = Math.max(6, Math.round(n * frac));
  const seed = mkHash(q.码 + '|' + q.名 + '|' + clock.day);
  const open = Math.max(.01, (q.prev || q.price) * (1 + q.chg * .22 + (mkRnd(seed ^ 0x5bd1) - .5) * amp * .3));
  const step = amp * .4 * Math.sqrt(3 / m), walk = [0];
  for (let i = 1; i < m; i++) walk.push(walk[i - 1] + (mkRnd(seed + i * 7919) * 2 - 1) * step);
  const drift = (walk[m - 1] - walk[0]) / (m - 1);
  const out = [];
  for (let i = 0; i < m; i++) {
    const t = i / (m - 1);
    out.push(open * (1 + (q.price / open - 1) * t) * (1 + (walk[i] - walk[0] - drift * i)));
  }
  out[0] = open; out[m - 1] = q.price;      /* 端点严格对齐今开 / 现价 */
  return out;
}
function seriesStats(s) {
  let hi = -Infinity, lo = Infinity;
  for (let i = 0; i < s.length; i++) { if (s[i] > hi) hi = s[i]; if (s[i] < lo) lo = s[i]; }
  return { open: s[0], last: s[s.length - 1], hi: hi, lo: lo, amp: s[0] ? (hi - lo) / s[0] : 0 };
}
/** 迷你分时折线：颜色交给 CSS 的 .up/.down/.flat，随手机会皮肤走 */
function sparkline(s, tone) {
  const W = 100, H = 30, n = s.length, pad = 3.5, st = seriesStats(s),
    span = (st.hi - st.lo) || (Math.abs(st.hi) * .002) || 1;
  const X = i => ((i / (n - 1)) * W).toFixed(2);
  const Y = v => (H - pad - ((v - st.lo) / span) * (H - pad * 2)).toFixed(2);
  let d = 'M' + X(0) + ' ' + Y(s[0]);
  for (let i = 1; i < n; i++) d += 'L' + X(i) + ' ' + Y(s[i]);
  return `<svg class="ph-spark ${tone}" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true">` +
    `<path class="ph-spark-area" d="${d}L${W} ${H}L0 ${H}Z"/><path class="ph-spark-line" d="${d}"/></svg>`;
}
/** 账户总览：全部由既有资产节点派生，不新增任何数据节点 */
function acctCard(mv, fl, rate) {
  const cny = walletOf('人民币'), usd = walletOf('美元'), done = realizedPL(), total = cny + usd * rate + mv;
  return `<div class="ph-acct"><div class="ph-acct-main"><small>总资产 · 元</small><b>${moneyTxt(total)}</b>` +
    `<i class="${fl >= 0 ? 'up' : 'down'}">浮动 ${fl >= 0 ? '+' : ''}${moneyTxt(fl)}</i></div>` +
    `<div class="ph-acct-grid">` +
    `<span><small>持仓市值</small><em>${moneyTxt(mv)}</em></span>` +
    `<span><small>可用资金</small><em>${moneyTxt(cny)}</em></span>` +
    `<span><small>已实现</small><em class="${done >= 0 ? 'up' : 'down'}">${done >= 0 ? '+' : ''}${moneyTxt(done)}</em></span>` +
    `<span><small>汇率</small><em>${money2(rate)}</em></span>` +
    `</div></div>`;
}
/** 顶部跑马灯：涨跌幅最大的几只（纯展示；减少动效偏好下自动静止） */
function tape(quotes) {
  const list = quotes.filter(q => !q.flag).slice().sort((a, b) => Math.abs(b.chg) - Math.abs(a.chg)).slice(0, 8);
  if (!list.length) return '';
  const one = q => `<span class="ph-tape-i ${q.chg >= 0 ? 'up' : 'down'}">${esc(q.名)} ${q.chg >= 0 ? '▲' : '▼'}${pct(q.chg)}</span>`;
  const strip = list.map(one).join('');
  return `<div class="ph-tape" aria-hidden="true"><div class="ph-tape-run">${strip}${strip}</div></div>`;
}
function quoteRow(q, held, lots, clock) {
  const tone = q.flag ? 'flat' : (q.chg > .0005 ? 'up' : (q.chg < -.0005 ? 'down' : 'flat'));
  const s = q.flag ? null : intradaySeries(q, clock), st = s ? seriesStats(s) : null;
