  const btns = (q.canBuy ? `<button type="button" class="ph-btn buy" data-act="buy" data-arg="${esc(q.名)}">买入 ${lots === 'all' ? '全仓' : lots + '手'}</button>` : '') +
    (q.canSell ? `<button type="button" class="ph-btn sell" data-act="sell" data-arg="${esc(q.名)}">卖出</button>` : '');
  return `<article class="ph-mk ${tone}">
<div class="ph-mk-top">
<div class="ph-mk-name"><b>${esc(q.名)}</b><small>${esc(q.码)} · ${esc(q.板)}${held ? ' · 持 ' + held + ' 股' : ''}</small></div>
<div class="ph-mk-quote"><em class="${tone}">${esc(q.venue.符)}${money2(q.price)}</em><span class="ph-mk-badge ${tone}">${q.flag ? esc(q.flag.k) : pct(q.chg)}</span></div>
</div>
${s ? `<div class="ph-mk-mid">${sparkline(s, tone)}
<div class="ph-mk-stats"><span>今开 <i>${money2(st.open)}</i></span><span>最高 <i class="ph-up">${money2(st.hi)}</i></span><span>最低 <i class="ph-dn">${money2(st.lo)}</i></span><span>振幅 <i>${(st.amp * 100).toFixed(2)}%</i></span></div>
</div>` : (q.flag ? `<div class="ph-mk-note">${esc(q.flag.t)}</div>` : '')}
${(tags || btns) ? `<div class="ph-mk-foot">${tags}<span class="ph-mk-btns">${btns}</span></div>` : ''}
</article>`;
}
function pageStock() {
  const w = statWorld(), clock = worldClock();
  if (!clock) {
    const why = parseWorldTime(w.当前时间)
      ? '当前界域是「' + val(w.当前界域, '未记录') + '」，不是地球'
      : '世界时间「' + val(w.当前时间, '未记录') + '」里解析不出年月日';
    return '<div class="ph-empty">此地此时没有股市<br><small>' + esc(why) + '<br>股市只在「地球」界域、且能解析出故事时间时开放</small></div>';
  }
  const quotes = quoteAll(clock), rate = fxRate(clock.day), lots = num(STORE.stock.lots, 1) || 1;
  const lotsSel = STORE.stock.lots === 'all' ? 'all' : lots;
  const holds = rows(holdBox());
  const valueOf = q => q.price * (q.市 === 'us' ? rate : 1);
  let mv = 0, fl = 0;
  holds.forEach(([n, d]) => {
    const q = quotes.find(s => s.名 === n);
    if (!q) return;
    const h = leafNum(obj(d), '股数'), c = leafNum(obj(d), '成本');
    mv += valueOf(q) * h;
    fl += (valueOf(q) - c * (q.市 === 'us' ? rate : 1)) * h;
  });
  const halted = quotes.filter(q => q.flag).length;
  const sub = uiGet().s_stock || 'a';
  /* v1.9.5-ui.5：账户总览 + 指数卡 + 跑马灯取代原来的胶囊行；
     「下单量」改为独立的标签 + 分段委托量（原来是裸 span.ph-chip，被 flex 拉伸/压窄才错位） */
  const extras = (walletOf('美元') || halted) ? '<div class="ph-chips">' +
    (walletOf('美元') ? chip('美元账户 ' + moneyTxt(walletOf('美元'))) : '') +
    (halted ? chip('停牌 ' + halted, 'warn') : '') + '</div>' : '';
  const lotBar = '<div class="ph-lotbar"><span class="ph-lot-lab">下单量</span><span class="ph-lot-opts">' +
    [1, 2, 5, 10, 'all'].map(n => `<button type="button" class="ph-chip${String(lotsSel) === String(n) ? ' on' : ''}" data-lots="${n}">${n === 'all' ? '全仓' : n + '手'}</button>`).join('') +
    '</span></div>';
  const tabs = '<div class="ph-tabs">' +
    [['a', '沪深', quotes.filter(q => q.市 === 'a').length], ['us', '美股', quotes.filter(q => q.市 === 'us').length],
     ['hold', '持仓', holds.length], ['ai', 'AI 操盘', arr(STORE.stock.log).length]]
      .map(([k, label, n]) => `<button type="button" class="${k === sub ? 'on' : ''}" data-s="stock:${k}">${esc(label)}<i>${pad2(n)}</i></button>`).join('') +
    '</div>';
  let body = '';
  if (sub === 'hold') {
    body = holds.length ? holds.map(([n, d]) => {
      const h = leafNum(obj(d), '股数'), c = leafNum(obj(d), '成本'), q = quotes.find(s => s.名 === n);
      const mul = q && q.市 === 'us' ? rate : 1;
      const f = q ? (valueOf(q) - c * mul) * h : 0;
      const cur = q ? valueOf(q) * h : 0, base = c * mul * h, fpc = base ? f / base : 0;
      const tone = f > 0 ? 'up' : (f < 0 ? 'down' : 'flat');
      const weight = mv > 0 ? Math.min(100, (cur / mv) * 100) : 0;
      return `<article class="ph-hd ${tone}">
<div class="ph-mk-top">
<div class="ph-mk-name"><b>${esc(n)}</b><small>${h} 股 · 成本 ${money2(c)}${q ? ' · 现价 ' + money2(q.price) : ' · 已无行情'}</small></div>
<div class="ph-mk-quote"><em class="${tone}">${f >= 0 ? '+' : ''}${moneyTxt(f)}</em><span class="ph-mk-badge ${tone}">${q ? pct(fpc) : '无行情'}</span></div>
</div>
<div class="ph-hd-bar"><i style="width:${weight.toFixed(1)}%"></i></div>
<div class="ph-mk-foot"><span class="ph-hd-mv">市值 ${moneyTxt(cur)} · 占仓 ${weight.toFixed(1)}%</span>
<span class="ph-mk-btns"><button type="button" class="ph-btn sell" data-act="sell" data-arg="${esc(n)}" ${q && q.canSell ? '' : 'disabled'}>卖出</button></span></div></article>`;
    }).join('') : '<div class="ph-empty">尚无持仓<br><small>在行情里买入第一手</small></div>';
  } else if (sub === 'ai') {
