      '<div class="ph-row"><button type="button" class="ph-btn" data-act="ai-trade" data-ai-busy="让 AI 操盘">让 AI 操盘</button>' +
      '<button type="button" class="ph-btn ghost" data-act="ai-auto">' + (STORE.stock.auto ? '关掉自动' : '开启自动') + '</button>' +
      '<button type="button" class="ph-btn ghost" data-act="ai-clear">清空记录</button></div>' +
      '<div class="ph-hint">已计 ' + num(STORE.stock.count, 0) + ' / ' + num(STORE.stock.every, 3) + ' 层；到点自动让 AI 操盘一次。</div>' +
      (log.length ? log.map(l => `<div class="ph-sec" style="margin:0 0 8px"><h4>${esc(l.t || '')}<i>${l.kind === 'auto' ? '自动' : '手动'}</i></h4>
<div class="ph-quote">${esc(l.复盘 || '（无复盘）')}${l.备注 ? '\n' + esc(l.备注) : ''}</div>
${arr(l.成交).map(x => '<div class="ph-me"><b>成交</b>' + esc(x) + '</div>').join('')}
${arr(l.失败).map(x => '<div class="ph-cm"><b>放弃</b>' + esc(x) + '</div>').join('')}</div>`).join('') : '<div class="ph-empty">还没有操盘记录</div>') +
      '</div>';
  } else {
    const list = quotes.filter(q => q.市 === sub);
    body = list.length ? list.map(q => quoteRow(q, leafNum(obj(holdBox()[q.名]), '股数'), lotsSel, clock)).join('')
      : '<div class="ph-empty">该市场暂无股票</div>';
  }
  return tape(quotes) + acctCard(mv, fl, rate) +
    '<div class="ph-mkt">' + idxCard(quotes, 'a') + idxCard(quotes, 'us') + '</div>' +
    extras + lotBar + tabs + body;
}

