#ph-mask{position:fixed;left:0;top:0;right:0;bottom:0;z-index:2147482001;display:none;background:rgba(8,6,4,.72);
  -webkit-backdrop-filter:blur(12px);backdrop-filter:blur(12px)}
#ph-mask.on{display:block}
#ph-root .ph-in{display:flex;flex-direction:column;min-height:0;flex:1}
/* 浮窗模式：1px 渐变描边 + 暗色内衬（居中由 JS 用 left/top 反推环境偏移摆位） */
#ph-root[data-mode="float"]{width:min(560px,94vw);height:min(76vh,700px);max-width:none;max-height:min(80vh,780px);
  padding:1px;border:0;border-radius:16px;
  background:linear-gradient(135deg,var(--ph-gold),rgba(122,90,50,.85),rgba(243,224,176,.9),var(--ph-gold));
  background-size:240% 240%;animation:csmgPhGlow 9s ease infinite;
  box-shadow:0 24px 64px rgba(0,0,0,.75),0 0 32px var(--ph-golddim)}
#ph-root[data-mode="float"] .ph-in{border-radius:15px;overflow:hidden;
  background:linear-gradient(180deg,var(--ph-void2),var(--ph-void))}
#ph-root[data-mode="float"] #ph-bar{cursor:default}
#ph-root[data-mode="float"] #ph-bar h3{letter-spacing:.28em;
  background:linear-gradient(90deg,var(--ph-paper),var(--ph-gold),var(--ph-paper));
  -webkit-background-clip:text;background-clip:text;color:transparent}
#ph-root[data-mode="float"] #ph-close{border-radius:50%;border:1px solid rgba(212,91,82,.4);
  background:rgba(20,12,10,.45);color:#f0a8a0}
#ph-root[data-mode="float"] #ph-nav{gap:4px;padding:8px 10px;border-top:1px solid var(--ph-line)}
#ph-root[data-mode="float"] #ph-nav button{border:1px solid var(--ph-line2);border-radius:999px;
  padding:6px 0;background:rgba(255,255,255,.02);color:var(--ph-mute);letter-spacing:.06em}
#ph-root[data-mode="float"] #ph-nav button.on{color:var(--ph-paper);border-color:var(--ph-goldline);
  background:linear-gradient(135deg,var(--ph-golddim),rgba(122,90,50,.16))}
@keyframes csmgPhGlow{0%,100%{background-position:0% 50%}50%{background-position:100% 50%}}
#ph-conn{flex:0 0 auto;display:none;padding:5px 12px;font:400 11px var(--ph-mono);color:#f4f0e6;background:#8a4b3a;text-align:center}
#ph-root[data-conn="off"] #ph-conn{display:block}
#ph-bar{flex:0 0 auto;display:flex;align-items:center;gap:8px;padding:10px 12px;border-bottom:1px solid var(--ph-line);background:var(--ph-void2)}
#ph-bar h3{margin:0;font:500 13px var(--ph-serif);color:var(--ph-gold);letter-spacing:.08em;flex:1}
#ph-bar time{font:400 11px var(--ph-mono);color:var(--ph-mute)}
#ph-bar button{all:unset;cursor:pointer;width:24px;height:24px;display:grid;place-items:center;color:var(--ph-mute);border-radius:6px}
#ph-bar button:hover{color:var(--ph-gold);background:var(--ph-golddim)}
#ph-bar button svg{width:15px;height:15px;stroke:currentColor;fill:none;stroke-width:1.7;stroke-linecap:round}
#ph-body{flex:1;min-height:0;overflow-y:auto;padding:12px;scrollbar-width:thin}
#ph-nav{flex:0 0 auto;display:flex;border-top:1px solid var(--ph-line);background:var(--ph-void2)}
#ph-nav button{all:unset;cursor:pointer;flex:1;padding:9px 0;text-align:center;font:400 11px var(--ph-sans);color:var(--ph-mute)}
#ph-nav button.on{color:var(--ph-gold)}
#ph-nav button b{display:block;font:500 12px var(--ph-serif)}
#ph-root .ph-sec{margin:0 0 14px}
#ph-root .ph-sec>h4{margin:0 0 8px;font:500 12px var(--ph-serif);color:var(--ph-gold);letter-spacing:.06em;display:flex;align-items:center;gap:6px}
#ph-root .ph-sec>h4 i{font:400 10px var(--ph-mono);color:var(--ph-dim);font-style:normal;margin-left:auto}
#ph-root .ph-post{position:relative;padding:10px 11px;margin:0 0 8px;border:1px solid var(--ph-line);background:rgba(255,255,255,.015);cursor:pointer;transition:border-color .15s}
#ph-root .ph-post:hover{border-color:var(--ph-line2)}
#ph-root .ph-post h5{margin:0 0 4px;font:500 13px var(--ph-sans);color:var(--ph-paper)}
#ph-root .ph-post p{margin:0;font-size:12px;color:var(--ph-soft);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
#ph-root .ph-post i{display:block;margin-top:5px;font:400 10px var(--ph-mono);color:var(--ph-dim);font-style:normal}
#ph-root .ph-tag{display:inline-block;padding:1px 6px;margin-right:4px;font:400 10px var(--ph-mono);color:var(--ph-gold);border:1px solid var(--ph-goldline)}
#ph-root .ph-quote{padding:10px;border-left:2px solid var(--ph-goldline);background:var(--ph-golddim);font-size:12px;color:var(--ph-soft);white-space:pre-wrap}
#ph-root .ph-cm{padding:7px 0;border-bottom:1px dashed var(--ph-line);font-size:12px}
#ph-root .ph-cm b{color:var(--ph-gold);font-weight:400;margin-right:6px}
#ph-root .ph-me{padding:7px 0;border-bottom:1px dashed var(--ph-line);font-size:12px}
#ph-root .ph-me b{color:var(--ph-mana);font-weight:400;margin-right:6px}
#ph-root .ph-empty{padding:24px 4px;text-align:center;color:var(--ph-dim);font-size:12px}
#ph-root .ph-role{display:flex;align-items:center;gap:8px;padding:9px 10px;margin:0 0 7px;border:1px solid var(--ph-line);cursor:pointer}
#ph-root .ph-role:hover{border-color:var(--ph-line2)}
#ph-root .ph-av{flex:0 0 auto;width:30px;height:30px;display:grid;place-items:center;font:500 13px var(--ph-serif);color:var(--ph-void);background:var(--ph-gold)}
#ph-root .ph-role div{min-width:0;flex:1}
#ph-root .ph-role b{display:block;font:400 13px var(--ph-sans)}
#ph-root .ph-role small{display:block;color:var(--ph-dim);font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#ph-root .ph-bub{max-width:78%;padding:8px 10px;margin:0 0 8px;font-size:12px;white-space:pre-wrap;word-break:break-word;border:1px solid var(--ph-line)}
#ph-root .ph-bub.in{background:rgba(255,255,255,.03);color:var(--ph-soft)}
#ph-root .ph-bub.out{margin-left:auto;background:var(--ph-golddim);border-color:var(--ph-goldline);color:var(--ph-paper)}
#ph-root .ph-bub time{display:block;margin-top:4px;font:400 10px var(--ph-mono);color:var(--ph-dim)}
#ph-root .ph-bub .ph-del{all:unset;cursor:pointer;margin-left:8px;padding:0 4px;color:var(--ph-dim);font-size:11px}
#ph-root .ph-bub .ph-del:hover{color:#e06a5e}
/* 剧情发言（读自聊天记录）：不分左右，左侧用情绪色描边，与卡内 .csmg-say 的配色一致 */
