#ph-root .ph-bub.log.t-gold{border-left-color:#ffd277}
#ph-root .ph-bub.log.t-pink{border-left-color:#ff91c8}
#ph-root .ph-bub.log.t-blue{border-left-color:#a9c8ff}
#ph-root .ph-bub.log.t-red{border-left-color:#ff665c}
#ph-root .ph-bub.log.t-lime{border-left-color:#e9ff86}
#ph-root .ph-bub.log.t-green{border-left-color:#7ee6a2}
#ph-root .ph-bub.log.t-purple{border-left-color:#c89cff}
/* 「正文里说过的话」折叠条：默认收起，不铺开酒馆历史 */
#ph-root .ph-logfold{margin-top:12px;padding-top:10px;border-top:1px solid var(--ph-line)}
#ph-root button.ph-fold{all:unset;cursor:pointer;display:flex;align-items:center;gap:8px;box-sizing:border-box;width:100%;
  padding:7px 9px;font:400 12px var(--ph-sans);color:var(--ph-mute);
  background:rgba(255,255,255,.02);border:1px solid var(--ph-line)}
#ph-root button.ph-fold b{font-weight:400;color:var(--ph-soft)}
#ph-root button.ph-fold i{font-style:normal;font-size:11px;color:var(--ph-dim)}
#ph-root button.ph-fold em{margin-left:auto;font-style:normal;color:var(--ph-gold)}
#ph-root button.ph-fold:hover{border-color:var(--ph-goldline)}
#ph-root button.ph-fold.on em{color:var(--ph-dim)}
#ph-root .ph-loglist{margin-top:8px}
#ph-send{display:flex;gap:6px;padding:9px 12px;border-top:1px solid var(--ph-line);background:var(--ph-void2)}
#ph-send textarea{flex:1;min-height:38px;max-height:110px;resize:none;padding:8px 9px;font:400 12px var(--ph-sans);
  color:var(--ph-paper);background:rgba(255,255,255,.03);border:1px solid var(--ph-line);outline:none}
#ph-send textarea:focus{border-color:var(--ph-goldline)}
#ph-send button,#ph-root button.ph-btn{all:unset;cursor:pointer;padding:0 13px;font:400 12px var(--ph-sans);color:var(--ph-void);
  background:var(--ph-gold);border:1px solid var(--ph-gold);text-align:center}
#ph-send button:disabled,#ph-root button.ph-btn:disabled{opacity:.45;cursor:default}
#ph-root button.ph-btn.ghost{background:transparent;color:var(--ph-gold);border-color:var(--ph-goldline)}
#ph-root .ph-row{display:flex;gap:6px;flex-wrap:wrap;margin:0 0 10px}
#ph-root .ph-f{display:block;margin:0 0 9px}
#ph-root .ph-f span{display:block;margin-bottom:3px;font-size:11px;color:var(--ph-mute)}
#ph-root .ph-f input,#ph-root .ph-f select,#ph-root .ph-f textarea{width:100%;box-sizing:border-box;padding:7px 8px;font:400 12px var(--ph-sans);
  color:var(--ph-paper);background:rgba(255,255,255,.03);border:1px solid var(--ph-line);outline:none}
/* 下拉框可读性：原生 option 在暗色主题下常渲染成白底白字，显式指定深色 */
#ph-root select{color:var(--ph-paper);background:rgba(255,255,255,.03)}
#ph-root select option{background:#161a23;color:var(--ph-paper)}
#ph-root select option:checked{background:#2a3040;color:#fff}
#ph-root .ph-f input:focus,#ph-root .ph-f select:focus,#ph-root .ph-f textarea:focus{border-color:var(--ph-goldline)}
#ph-root .ph-f textarea{min-height:96px;resize:vertical;line-height:1.5}
/* 输入框 + 按钮同一行（获取模型 / 保存预设 / 删除预设） */
#ph-root .ph-inline{display:flex;gap:6px;align-items:stretch}
#ph-root .ph-inline input,#ph-root .ph-inline select{flex:1 1 auto;min-width:0;width:auto}
#ph-root .ph-inline button{flex:0 0 auto;white-space:nowrap;padding:0 10px}
/* 切换模块（论坛 / 传讯 / 股市 / 设置）时的进入动画 */
#ph-body.ph-anim{animation:phIn .28s cubic-bezier(.2,.8,.2,1) both}
@keyframes phIn{from{opacity:0;transform:translateY(7px)}to{opacity:1;transform:none}}
#ph-root .ph-hint{font-size:11px;color:var(--ph-dim);margin:-4px 0 10px}
#ph-root .ph-hint code{font:400 11px var(--ph-mono);color:var(--ph-gold)}
