#ph-typing{padding:0 12px 8px;font-size:11px;color:var(--ph-gold)}
#ph-typing::after{content:'';display:inline-block;width:6px;height:6px;margin-left:6px;border-radius:50%;background:var(--ph-gold);animation:phpulse 1s infinite}
@keyframes phpulse{0%,100%{opacity:.25}50%{opacity:1}}
#ph-toast{position:fixed;z-index:2147482002;left:50%;bottom:44px;transform:translate(-50%,10px);padding:8px 14px;
  font:400 12px -apple-system,"PingFang SC","Microsoft YaHei",sans-serif;color:#f4f0e6;background:rgba(9,11,16,.95);
  border:1px solid rgba(212,176,122,.4);opacity:0;pointer-events:none;transition:.2s;max-width:70vw;text-align:center}
#ph-toast.on{opacity:1;transform:translate(-50%,0)}
/* 股市 / 子页签 / 胶囊 */
#ph-root .ph-chips{display:flex;flex-wrap:wrap;gap:4px;margin:0 0 9px}
#ph-root .ph-chip{display:inline-block;padding:2px 8px;font:400 11px var(--ph-mono);color:var(--ph-mute);
  border:1px solid var(--ph-line2);border-radius:999px;background:rgba(255,255,255,.02)}
#ph-root .ph-chip.on{color:var(--ph-paper);border-color:var(--ph-goldline);background:var(--ph-golddim)}
#ph-root .ph-chip.up{color:#e06a5e;border-color:rgba(224,106,94,.42)}
#ph-root .ph-chip.down{color:#5fa87a;border-color:rgba(95,168,122,.42)}
#ph-root .ph-chip.warn{color:#e0b25e;border-color:rgba(224,178,94,.42)}
#ph-root button.ph-chip{all:unset;cursor:pointer;padding:2px 9px;font:400 11px var(--ph-mono);
  color:var(--ph-mute);border:1px solid var(--ph-line2);border-radius:999px;background:rgba(255,255,255,.02)}
#ph-root button.ph-chip:hover{border-color:var(--ph-line2);color:var(--ph-paper)}
#ph-root button.ph-chip.on{color:var(--ph-paper);border-color:var(--ph-goldline);background:var(--ph-golddim)}
#ph-root .ph-tabs{display:flex;gap:4px;margin:0 0 10px}
#ph-root .ph-tabs button{flex:1;padding:5px 0;border:1px solid var(--ph-line2);border-radius:999px;background:rgba(255,255,255,.02);
  color:var(--ph-mute);font:400 11px var(--ph-sans);cursor:pointer;text-align:center}
#ph-root .ph-tabs button.on{color:var(--ph-paper);border-color:var(--ph-goldline);background:linear-gradient(135deg,var(--ph-golddim),rgba(122,90,50,.16))}
#ph-root .ph-tabs button i{font:400 10px var(--ph-mono);color:var(--ph-dim);font-style:normal;margin-left:4px}
#ph-root .ph-mk{display:block;padding:8px 10px;margin:0 0 7px;border:1px solid var(--ph-line);background:rgba(255,255,255,.015)}
