#ph-root .down{color:#5fa87a}
#ph-root .flat{color:var(--ph-mute)}
#ph-root .ph-sec .ph-role em{margin-left:auto}
/* ★ 面板模式下的调整大小手柄（左上角，向↖拖=变大，向↘拖=变小） */
#ph-resize{position:absolute;left:0;top:0;width:22px;height:22px;display:none;
  z-index:20;cursor:nwse-resize;touch-action:none;
  -webkit-user-select:none;user-select:none}
