#ph-resize::before{content:'';position:absolute;left:4px;top:4px;width:10px;height:10px;
  border-left:2px solid var(--ph-gold);border-top:2px solid var(--ph-gold);
  border-top-left-radius:3px;opacity:.4;transition:opacity .15s;pointer-events:none}
