@media(max-width:820px){
  #ph-root[data-mode="panel"]{max-width:calc(100vw - 24px);max-height:min(calc(100vh - 96px),620px)}
}

/* 灵机 UI refinement — all rules are scoped to the phone. */
#ph-root{--ph-void:#10141d;--ph-void2:#171d28;--ph-paper:#eee9dd;--ph-soft:#c8cbd1;--ph-mute:#a0a7b4;--ph-dim:#929baa;--ph-line:rgba(188,202,224,.11);--ph-line2:rgba(188,202,224,.2);--ph-gold:#dabd89;--ph-golddim:rgba(218,189,137,.1);--ph-goldline:rgba(218,189,137,.28);--ph-card:rgba(255,255,255,.035);--ph-input:rgba(0,0,0,.16);font-size:13px;line-height:1.75;text-shadow:none;isolation:isolate;container-type:inline-size}
