#ph-root[data-mode="float"]{border:1px solid var(--ph-goldline);padding:0;border-radius:26px;background:var(--ph-void);animation:none;max-height:none;box-shadow:0 28px 90px #0008,0 1px 0 #ffffff12 inset}
