#ph-root[data-mode="float"] .ph-in{border-radius:25px;background:var(--ph-void)}
#ph-mask{background:rgba(7,10,17,.58);backdrop-filter:blur(9px);-webkit-backdrop-filter:blur(9px)}
#ph-root #ph-bar{gap:10px;padding:15px 18px;border-bottom:1px solid var(--ph-line);background:var(--ph-void2)}
