/* ---------- 仙网（对应变量「互联网」）：风闻 / 论坛 / 日报 ---------- */
const flatTags = t => Array.isArray(t) ? t.join(' ') : String(val(t, ''));
/** 判定一条内容属于哪一栏：优先用显式「类型」，老数据靠平台/标签/标题猜 */
function postKind(key, p) {
  const t = String(val(obj(p).类型, ''));
  if (t === '风闻' || t === '论坛' || t === '日报') return t;
  const s = [val(obj(p).平台, ''), flatTags(obj(p).标签), String(key), String(val(obj(p).标题, ''))].join(' ');
  if (/日报|早报|晚报|邸报|头条|简报|新闻/.test(s)) return '日报';
  if (/风闻|传闻|流言|爆料|目击|异象|警示|求证|小道/.test(s)) return '风闻';
  return '论坛';
}
const likedPost = key => !!obj(STORE.likes)[key];
function pageForum() {
  const posts = statPosts(), keys = Object.keys(posts);
  const open = uiGet().forumPost;
  if (open && posts[open]) return postDetail(open, obj(posts[open]));
