/* ============ 额外模型的「模型来源 / 预设 / 获取模型」 ============
   参考 MVU 额外模型解析配置那一套：
     · 模型来源只有两个值 ——「与插头相同」（跟随 ST 当前模型）与「自定义」
     · 选「自定义」时才用下面填的地址 / 密钥 / 模型，并可用「API 方案」存取多套配置
   本脚本对应实现：presets（全局共享的预设列表）+ 每套自己的 profile（当前套用的预设名）。
   拉模型列表走 OpenAI 兼容的 {base}/models（浏览器直连，所以地址需允许跨域）。 */

/** 规范化 API 基址：去尾斜杠、去掉常见的端点尾巴 */
function normBase(u) {
  let s = String(u || '').trim();
  if (!s) return '';
  s = s.replace(/\/+$/, '');
  s = s.replace(/\/(chat\/completions|completions|models)$/i, '');
  return s;
}
/** 从各种返回结构里挑出模型名：{data:[{id}]} / {models:[...]} / [ ... ] / {data:[str]} */
function pickModels(j) {
  const o = obj(j);
  const list = Array.isArray(j) ? j
    : (arr(o.data).length ? o.data : (arr(o.models).length ? o.models : []));
  const out = [];
  arr(list).forEach(it => {
    const s = String(typeof it === 'string' ? it : (obj(it).id || obj(it).name || obj(it).model || '')).trim();
    if (s && out.indexOf(s) < 0) out.push(s);
  });
  return out.slice(0, 300);
}
/** 点「获取模型」：直连 {base}/v1/models 与 {base}/models，取到就存进 STORE.models */
async function fetchModels(prefix) {
  const c = obj(STORE[prefix]);
  const base = normBase(c.apiurl);
  if (!base) { toast('先在「API 地址」里填地址'); return; }
  const urls = /\/v\d+$/i.test(base) ? [base + '/models'] : [base + '/v1/models', base + '/models'];
  let err = null;
  await withBusy(null, '获取模型', async () => {
    for (const u of urls) {
      try {
        const r = await fetch(u, { headers: c.key ? { Authorization: 'Bearer ' + String(c.key) } : {} });
        if (!r.ok) throw new Error('HTTP ' + r.status);
        const list = pickModels(await r.json());
        if (list.length) {
          STORE.models = Object.assign(obj(STORE.models), { [prefix]: list });
          saveStore(); renderAll();
          toast('拉到 ' + list.length + ' 个模型，已列在下面');
          return;
        }
        err = new Error('返回里没有模型列表');
      } catch (e) { err = e; }
    }
    renderAll();
    toast('获取模型失败：' + ((err && err.message) || '未知错误') + '（浏览器直连被跨域拦时，请换成允许跨域的地址）');
  });
}
const presetOf = name => arr(STORE.presets).find(p => String(obj(p).名称) === String(name)) || null;
/** 把某套当前的地址/密钥/模型存成一个预设（同名覆盖） */
function savePreset(prefix, name) {
  const c = obj(STORE[prefix]);
  const nm = String(name || '').trim() || String(c.profile || '').trim() || ('方案 ' + (arr(STORE.presets).length + 1));
  const item = {
    名称: nm,
    apiurl: String(c.apiurl || ''),
    key: String(c.key || ''),
    model: String(c.model || ''),
    source: String(c.source || 'openai'),
  };
  STORE.presets = arr(STORE.presets).filter(p => String(obj(p).名称) !== nm).concat([item]);
  STORE[prefix] = Object.assign({}, c, { profile: nm, mode: 'api' });
  saveStore(); renderAll();
  toast('已保存预设「' + nm + '」');
}
/** 套用预设到某套配置 */
function usePreset(prefix, name) {
  const p = presetOf(name);
  const c = obj(STORE[prefix]);
  if (!p) { STORE[prefix] = Object.assign({}, c, { profile: '' }); return false; }
  STORE[prefix] = Object.assign({}, c, {
    mode: 'api',
    profile: String(p.名称),
    apiurl: String(p.apiurl || ''),
    key: String(p.key || ''),
    model: String(p.model || ''),
    source: String(p.source || c.source || 'openai'),
  });
  return true;
}
