  catch (e) { console.error('[小手机] 渲染出错', e); return '<div class="ph-empty">渲染出错<br><small>' + esc(e && e.message ? e.message : e) + '</small></div>'; }
}
let clearReplyNext = false;
/* 设置页里未提交的草稿：换 body 前先存、换完再按「父页面是否主动改过」判断还原 */
const panelSets = {};
function captureDrafts(doc) {
  const drafts = {};
  try { doc.querySelectorAll('#ph-root [data-set]').forEach(el => { drafts[el.dataset.set] = el.value; }); } catch (e) {}
  return drafts;
}
function restoreDrafts(doc, drafts, lastMap) {
  try {
    doc.querySelectorAll('#ph-root [data-set]').forEach(el => {
      const k = el.dataset.set;
      const rendered = el.value;
      if (k in lastMap && lastMap[k] === rendered && k in drafts && drafts[k] !== rendered) el.value = drafts[k];
      lastMap[k] = rendered;
    });
  } catch (e) {}
}
let lastTab = null;
function phonePageHeading(u) {
  if ((u.tab === 'forum' && u.forumPost) || (u.tab === 'chat' && u.chatWith)) return '';
  /* v1.9.5-ui.4：移除四个页面右上角的方框字（原 .ph-page-seal 印章块） */
  const pages = {forum:['THE IMMORTAL NETWORK','仙网','世间风闻，尽在掌中。'],chat:['MESSAGES','传讯','山海虽远，一讯即达。'],stock:['MARKET & ASSETS','行情','观市间风云，理手中资产。'],setting:['PREFERENCES','偏好设置','让灵机更合你的习惯。']};
  const p = pages[u.tab] || pages.forum;
  return '<div class="ph-pagehead"><div><small>'+p[0]+'</small><h2>'+p[1]+'</h2><p>'+p[2]+'</p></div></div>';
}

function renderAll() {
  const doc = hostDoc();
  const root = doc.getElementById('ph-root');
  if (!root) return;
  const panels = Array.from(root.querySelectorAll('details[data-ph-section]'));
  if (panels.length) uiSet({settingPanels:Object.assign({},obj(uiGet().settingPanels),Object.fromEntries(panels.map(el => [el.dataset.phSection, el.open])))});
  const u = uiGet();
  root.dataset.skin = skinOf();
  const clock = doc.getElementById('ph-clock');
  if (clock) clock.textContent = worldTime();
  const body = doc.getElementById('ph-body');
  const drafts = captureDrafts(doc);
  const draft = doc.getElementById('ph-input');
  const draftVal = draft ? draft.value : '';
  const draftReply = (() => { const r = doc.querySelector('#ph-root [name=replytext]'); return r ? r.value : ''; })();
  if (body) {
    if (lastTab !== u.tab) {
      body.classList.remove('ph-anim');
      void body.offsetWidth;   // 强制 reflow，重启动画
      body.classList.add('ph-anim');
      lastTab = u.tab;
    }
    root.dataset.page = u.tab;
    body.innerHTML = phonePageHeading(u) + safeBody();
    body.querySelectorAll('[data-post],[data-chat]').forEach(el => { el.tabIndex = 0; el.setAttribute('role', 'button'); });
  }
  const nav = doc.getElementById('ph-nav');
  if (nav) nav.querySelectorAll('button').forEach(b => { b.classList.toggle('on', b.dataset.tab === u.tab); b.setAttribute('aria-pressed', String(b.dataset.tab === u.tab)); });
  restoreDrafts(doc, drafts, panelSets);
  // 输入栏：保留草稿
  const oldBar = doc.getElementById('ph-send');
  if (oldBar) oldBar.remove();
  const sb = sendBar();
  if (sb && body) {
    body.insertAdjacentHTML('afterend', sb);
    const box = doc.getElementById('ph-input');
    if (box && draftVal) box.value = draftVal;
  }
  if (!clearReplyNext && draftReply) {
    const r = doc.querySelector('#ph-root [name=replytext]');
    if (r) r.value = draftReply;
  }
  if (u.tab === 'chat' && u.chatWith && body) body.scrollTop = body.scrollHeight;
  clearReplyNext = false;
}

/* ============================== 交互 ============================== */
function restyle() {
  const root = hostDoc().getElementById('ph-root');
  if (root) root.dataset.skin = skinOf();
