/**
 * 浮窗模式：data-mode=float —— 位置由 placeRoot() 用实测反推法居中，不再依赖 CSS 摆位。
 * 面板模式：data-mode=panel —— 位置由 placeRoot() 用 desiredPanel（视口坐标）确定。
 */
function applyMode() {
  const mode = (STORE.launch === 'panel') ? 'panel' : 'float';
  const doc = hostDoc();
  const root = doc.getElementById('ph-root');
  if (!root) return mode;
  root.dataset.mode = mode;
  root.setAttribute('aria-modal', String(mode === 'float')); 
  desiredPanel = null;   /* 模式切换后重新计算面板默认位置 */
  placeRoot();           /* 用实测反推法摆位 */
  syncMask();
  return mode;
}
/** 只有「浮窗 + 已打开」才铺遮罩 */
function syncMask() {
  const doc = hostDoc();
  const mask = doc.getElementById('ph-mask');
  const root = doc.getElementById('ph-root');
  if (!mask || !root) return;
  mask.classList.toggle('on', root.classList.contains('on') && root.dataset.mode === 'float');
  if (mask.classList.contains('on')) placeMask();
}
const inFloatMode = () => { const r = hostDoc().getElementById('ph-root'); return !!r && r.dataset.mode === 'float'; };
function openPanel(on) {
  const doc = hostDoc();
  const root = doc.getElementById('ph-root');
  if (!root) return;
  const next = on === undefined ? !root.classList.contains('on') : !!on;
  if (next) dismissKeyboard(); /* ★ v1.9.1：打开前先收起键盘，避免触摸穿透唤醒输入框 */
  root.classList.toggle('on', next);
  const fab = doc.getElementById('ph-fab');
  if (fab) fab.classList.toggle('on', next);
  applyMode();
  uiSet({ open: next });
  if (next) { restyle(); renderAll(); placeRoot(); placeMask(); } else { syncMask(); }
}
