const BOOL_SETTING = ['forum.preview', 'forum.enabled', 'forum.includeChat', 'chat.enabled', 'chat.readLog', 'chat.includeLog', 'chat.includeText', 'chat.includeLore', 'stock.enabled', 'stock.auto', 'stock.writeToStat', 'net.auto', 'avatar.show', 'avatar.persona'];
function applySetting(path, value) {
  const parts = String(path || '').split('.');
  if (!parts[0]) return;
  // 切「模型预设」＝套用整套（地址 / 密钥 / 模型 / source），不是只存一个名字
  if (parts.length === 2 && parts[1] === 'profile') {
    usePreset(parts[0], String(value || ''));
    saveStore();
    return;
  }
  let v = value;
  if (/\.enabled$/.test(path) || BOOL_SETTING.indexOf(path) >= 0) v = (v === '1' || v === true || v === 'true');
  if (parts.length === 1) { STORE[parts[0]] = v; }
  else {
    let cur = STORE;
    for (let i = 0; i < parts.length - 1; i++) { if (!cur[parts[i]]) cur[parts[i]] = {}; cur = cur[parts[i]]; }
    cur[parts[parts.length - 1]] = v;
  }
  saveStore();
  if (parts[0] === 'skin') restyle();
  if (parts[0] === 'launch') applyMode();
}
/** 统一的动作入口 */
async function act(t, fields) {
  const u = uiGet();
  fields = obj(fields);
  if (t.id === 'ph-close') { openPanel(false); return; }
  if (t.id === 'ph-gear') {
    const themes = ['dusk','ivory','white','cinnabar','jade','ink'];
    STORE.skin = themes[(themes.indexOf(skinOf()) + 1) % themes.length];
    saveStore(); restyle();
    const selector = hostDoc().querySelector('#ph-root [data-set="skin"]');
    if (selector) selector.value = STORE.skin;
    toast('主题：' + ({dusk:'暮夜 · 鎏金',ivory:'宣纸 · 暖白',white:'纯白 · 晴昼',cinnabar:'朱砂 · 赤霞',jade:'青玉 · 松绿',ink:'水墨 · 银灰'}[STORE.skin]));
    return;
  }
  if (t.tab) { uiSet({ tab: t.tab, chatWith: t.tab === 'chat' ? u.chatWith : null, forumPost: t.tab === 'forum' ? u.forumPost : null }); renderAll(); return; }
  if (t.post) { uiSet({ forumPost: t.post }); renderAll(); return; }
  if (t.chat || t.act || t.id === 'ph-send-btn' || t.id === 'ph-reply-send') requirePhoneChat();
  if (t.chat) { importMessagesIntoThread(t.chat); clearUnread(t.chat); uiSet({ chatWith: t.chat }); renderAll(); return; }
  if (t.id === 'ph-reply-send') {
    const nm = fields.netname || '';
    const tx = fields.replytext || '';
    if (nm) { STORE.forum.netname = nm; saveStore(); }
    clearReplyNext = true;
    await doForumReply(u.forumPost, nm, tx);
    renderAll();
    return;
  }
  if (t.id === 'ph-send-btn') {
    if (u.chatWith && String(fields.phInput || '').trim()) await sendToContact(u.chatWith, fields.phInput);
    return;
  }
  if (t.act === 'back') { uiSet({ forumPost: null, chatWith: null }); renderAll(); return; }
  /* --- 子页签 / 下单量 / 股市 --- */
  if (t.s) { const parts = String(t.s).split(':'); uiSet({ ['s_' + parts[0]]: parts[1] }); renderAll(); return; }
  if (t.lots) { STORE.stock.lots = (t.lots === 'all') ? 'all' : Math.max(1, num(t.lots, 1)); saveStore(); renderAll(); return; }
  if (t.act === 'buy' || t.act === 'sell') {
    const lots = STORE.stock.lots === 'all' ? 'all' : Math.max(1, num(STORE.stock.lots, 1));
    await marketOrder(t.act === 'buy' ? '买入' : '卖出', t.arg, lots);
    return;
  }
  if (t.act === 'ai-trade') { await withBusy(null, '让 AI 操盘', () => runAITrade('manual')); return; }
  if (t.act === 'ai-auto') {
    STORE.stock.auto = !STORE.stock.auto; saveStore(); renderAll();
    toast(STORE.stock.auto ? '已开启自动操盘（每 ' + num(STORE.stock.every, 3) + ' 层）' : '已关闭自动操盘');
    return;
  }
  if (t.act === 'ai-clear') { STORE.stock.log = []; resetTradeCounter(); renderAll(); toast('操盘记录已清空'); return; }
  /* --- 仙网 / 传讯 --- */
  if (t.act === 'like') { await likePost(t.arg); return; }
  if (t.act === 'del-post') { await delPost(t.arg); return; }
  if (t.act === 'refresh') { await refreshNetAll(); return; }
  if (t.act === 'refresh-kind') { await refreshNetKind(t.arg); return; }
  if (t.act === 'newpost') { await genNewPost(); return; }
  if (t.act === 'aireply') { await doForumAI(u.forumPost); return; }
  if (t.act === 'del-chat') { delChat(t.arg || u.chatWith); return; }
  if (t.act === 'clear-chat') { clearChat(t.arg || u.chatWith); return; }
  if (t.act === 'del-msg') { delMsg(t.arg); return; }
  if (t.act === 'fetch-models') { await fetchModels(t.arg || 'forum'); return; }
  if (t.act === 'save-preset') { savePreset(t.arg || 'forum', obj(fields).presetName); return; }
  if (t.act === 'del-preset') { delPreset(t.arg || 'forum'); return; }
  if (t.act === 'reset-pos') { resetPhonePos(); return; }
  if (t.act === 'refresh-assets') {
    await withBusy(null, '刷新图床索引', async () => {
      try { await loadAssets(true); } catch (e) {}
      toast(avIdx.ready ? ('图床索引已刷新：' + Object.keys(avIdx.chars).length + ' 位角色有头像') : '图床索引没读到，请检查根地址与网络');
    });
    return;
  }
  if (t.act === 'import-mvu') {
    try {
      /* 新版酒馆里 globalThis.SillyTavern 只有 { libs, getContext }，扩展设置要从
         getContext().extensionSettings 取（旧版曾挂在 SillyTavern.extension_settings 上），两边都兼容。 */
      const SS = hostWin().SillyTavern || {};
      const es = obj(stCtx()).extensionSettings || SS.extension_settings || {};
      const m = (es.mvu_settings && es.mvu_settings['额外模型解析配置']) || {};
      const url = String(m['api地址'] || ''), model = String(m['模型名称'] || ''), key = String(m['密钥'] || '');
      // MVU 的「api方案列表」→ 手机的模型预设（同名覆盖）
      const merged = arr(STORE.presets).slice();
      arr(m['api方案列表']).forEach(p => {
        const d = obj(p);
        const nm = String(d.名称 || '').trim() || ('方案 ' + (merged.length + 1));
        const item = { 名称: nm, apiurl: String(d.api地址 || ''), key: String(d.密钥 || ''), model: String(d.模型名称 || ''), source: 'openai' };
        const i = merged.findIndex(x => String(obj(x).名称) === nm);
        if (i >= 0) merged[i] = item; else merged.push(item);
      });
      STORE.presets = merged;
      if (!url && !model && !merged.length) { toast('没找到 MVU 额外模型解析配置'); return; }
      [STORE.forum, STORE.chat, STORE.stock].forEach(c => {
        if (!c.apiurl) c.apiurl = url;
        if (!c.model) c.model = model;
        if (!c.key) c.key = key;
        c.source = 'openai';
      });
      saveStore(); renderAll();
      toast('已导入' + (merged.length ? '，含 ' + merged.length + ' 个 API 方案' : '') + '（只填空白字段）');
    } catch (err) { toast('导入失败：' + (err && err.message ? err.message : err)); }
    return;
  }
  if (t.act === 'reset-prompt') {
    STORE.forum.system = DEFAULT_FORUM_PROMPT;
    STORE.chat.system = DEFAULT_CHAT_PROMPT;
    STORE.stock.system = DEFAULT_TRADE_PROMPT;
    saveStore(); renderAll(); toast('已恢复默认提示词');
    return;
  }
  if (t.act === 'toggle-log') { uiSet({ logOpen: !uiGet().logOpen }); renderAll(); return; }
  if (t.act === 'reload-log') {
    resetStoryCache();
    resetLoreCache();
    scanChatLog(true);
    const c = scanChatLog();
    renderAll();
    toast(c.rows.length
      ? ('读到 ' + c.rows.length + ' 条剧情发言 · ' + c.names.length + ' 位说话人')
      : (chatLogOpt().on ? '没读到剧情发言：正文里需要 [说|角色|情绪|内容] 这样的标记' : '读取聊天记录已关闭'));
    return;
  }
  if (t.act === 'clear-chats') {
    STORE.chats = {}; STORE.unread = {}; saveStore(); renderAll();
    commitStat(st => {   // v1.9.3：同步清空「讯息」变量，否则几轮后又被导回
      const box = obj(st.讯息);
      Object.keys(box).forEach(k => { const m = obj(box[k]); if (m.内容 !== undefined || m.发送者 !== undefined) delete box[k]; });
      return { ok: true };
    });
    toast('聊天记录已清空（含「讯息」变量）');
    return;
  }
}
function bindEvents() {
  const doc = hostDoc();
  const root = doc.getElementById('ph-root');
  if (!root) return;
  const bar = doc.getElementById('ph-bar');
  if (bar) {
    /* ★ 面板拖动：只更新 desiredPanel（视口坐标），实际落点交给 placeRoot 反推偏移 */
    let dragPanel = null;
    bar.style.cursor = 'move';
    bar.addEventListener('pointerdown', e => {
      if (e.target.closest('button')) return;
      if (inFloatMode()) return;            // 浮窗是居中的，不拖动
      const cur = desiredPanel || (() => {
        const r = root.getBoundingClientRect();
        return { x: r.left, y: r.top };
      })();
      dragPanel = { startX: e.clientX, startY: e.clientY, origX: cur.x, origY: cur.y };
      try { bar.setPointerCapture(e.pointerId); } catch (err) {}
      e.preventDefault();
    });
    bar.addEventListener('pointermove', e => {
      if (!dragPanel) return;
      const { w, h } = hostViewport();
      desiredPanel = {
        x: clamp(dragPanel.origX + e.clientX - dragPanel.startX, 4, Math.max(4, w - 60)),
        y: clamp(dragPanel.origY + e.clientY - dragPanel.startY, 4, Math.max(4, h - 60)),
      };
      placeRoot();
    });
    bar.addEventListener('pointerup', () => {
      if (!dragPanel) return;
      dragPanel = null;
      if (desiredPanel) {
        const { w, h } = hostViewport();
        const nx = clamp(desiredPanel.x, 4, Math.max(4, w - 60));
        const ny = clamp(desiredPanel.y, 4, Math.max(4, h - 40));
        desiredPanel = { x: nx, y: ny };
        writeViewportPos(POS_PANEL_KEY, nx, ny);
        placeRoot();
      }
    });
  }
  /* ★ 调整大小：左上角手柄，固定右下角，向左/上拖 = 变大，向右/下拖 = 变小。
     手机与电脑共用同一套 pointer 事件，touch-action:none 已阻止页面跟着滚。 */
  const resizeHandle = doc.getElementById('ph-resize');
  if (resizeHandle) {
    let dragResize = null;
    resizeHandle.addEventListener('pointerdown', e => {
      if (inFloatMode()) return;
      e.preventDefault();
      e.stopPropagation();
      const rect = root.getBoundingClientRect();
      dragResize = {
        startX: e.clientX,
        startY: e.clientY,
        startW: rect.width,
        startH: rect.height,
        anchorRight: rect.left + rect.width,   /* 右下角：拖动过程中保持不动 */
        anchorBottom: rect.top + rect.height,
      };
      try { resizeHandle.setPointerCapture(e.pointerId); } catch (err) {}
    });
    resizeHandle.addEventListener('pointermove', e => {
      if (!dragResize) return;
      const dx = e.clientX - dragResize.startX;
      const dy = e.clientY - dragResize.startY;
      const { w, h } = hostViewport();
      const minW = 180, minH = 180;
      const maxW = Math.max(minW, w - 8);
      const maxH = Math.max(minH, h - 8);
      let newW = clamp(dragResize.startW - dx, minW, maxW);
      let newH = clamp(dragResize.startH - dy, minH, maxH);
      let newX = dragResize.anchorRight - newW;
      let newY = dragResize.anchorBottom - newH;
      newX = clamp(newX, 4, Math.max(4, w - newW - 4));
      newY = clamp(newY, 4, Math.max(4, h - newH - 4));
      desiredPanelSize = { w: newW, h: newH };
      desiredPanel = { x: newX, y: newY };
      placeRoot();
    });
    const endResize = e => {
      if (!dragResize) return;
      dragResize = null;
      if (desiredPanelSize) writePanelSize(desiredPanelSize.w, desiredPanelSize.h);
      if (desiredPanel) writeViewportPos(POS_PANEL_KEY, desiredPanel.x, desiredPanel.y);
      try { resizeHandle.releasePointerCapture(e.pointerId); } catch (err) {}
    };
    resizeHandle.addEventListener('pointerup', endResize);
    resizeHandle.addEventListener('pointercancel', endResize);
  }
  root.addEventListener('click', async e => {
    const t = e.target.closest('[data-tab],[data-post],[data-chat],[data-act],[data-lots],[data-s],#ph-close,#ph-gear,#ph-send-btn,#ph-reply-send');
    if (!t) return;
    const fields = readFields(doc);
    const box = doc.getElementById('ph-input');
    if (box) fields.phInput = box.value;
    if (t.id === 'ph-send-btn' && box) box.value = '';
    const desc = {
      id: t.id || '',
      tab: t.dataset.tab || '',
      post: t.dataset.post || '',
      chat: t.dataset.chat || '',
      act: t.dataset.act || '',
      arg: t.dataset.arg || '',
      lots: t.dataset.lots || '',
      s: t.dataset.s || '',
    };
    try { await act(desc, fields); }
    catch (err) { console.error('[小手机] 动作失败', err); toast('操作失败：' + (err && err.message ? err.message : err)); }
  });
  root.addEventListener('toggle', e => {
    const el = e.target;
    if (el.matches && el.matches('details[data-ph-section]')) uiSet({settingPanels:Object.assign({},obj(uiGet().settingPanels),{[el.dataset.phSection]:el.open})});
  }, true);
  root.addEventListener('keydown', e => {
    if (e.target.matches('[data-post],[data-chat]') && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); e.target.click(); return; }

    if (e.target.matches('textarea,input')) {
      e.stopPropagation();
      if (e.key === 'Enter' && (e.ctrlKey || e.metaKey) && e.target.id === 'ph-input') {
        const b = root.querySelector('#ph-send-btn');
        if (b) b.click();
      }
      if (e.key === 'Escape') e.target.blur();
    }
  }, true);
  root.addEventListener('change', e => {
    const uiEl = e.target.closest('[data-ui]');
    if (uiEl) { uiSet({ [uiEl.dataset.ui]: uiEl.value }); renderAll(); return; }
    const el = e.target.closest('[data-set]');
    if (!el) return;
    applySetting(el.dataset.set, el.type === 'number' ? num(el.value, 0) : el.value);
    renderAll();
  });
  try { hostWin().addEventListener('storage', ev => { if (ev && ev.key === LOOK_KEY) restyle(); }); } catch (e) {}
  try { ensureLore(true); } catch (e) { }   // 预热世界书，发消息时就能同步取到设定
  try { loadAssets(); } catch (e) { }       // 预热图床索引（先吃缓存，再后台拉最新）
  // 浮窗模式下 Esc 关窗
  try {
    doc.addEventListener('keydown', e => {
      if (e.key !== 'Escape') return;
      const r = doc.getElementById('ph-root');
      if (r && r.classList.contains('on') && r.dataset.mode === 'float') openPanel(false);
    });
  } catch (e) {}
}

/* ============================== DOM ============================== */
function ensureDom() {
  const doc = hostDoc();
  if (!doc.getElementById('ph-style')) {
    const st = doc.createElement('style');
    st.id = 'ph-style';
    st.textContent = PHONE_CSS;
    (doc.head || doc.documentElement).appendChild(st);
  }
  if (!doc.getElementById('ph-toast')) {
    const t = doc.createElement('div');
    t.id = 'ph-toast';
    t.setAttribute('role', 'status'); t.setAttribute('aria-live', 'polite');
    doc.body.appendChild(t);
  }
  if (!doc.getElementById('ph-fab')) {
    const f = doc.createElement('div');
    f.id = 'ph-fab';
    f.setAttribute('role', 'button');
    f.setAttribute('tabindex', '0');
    f.title = '小手机（左键打开，右键打开角落小面板）';
    f.innerHTML = ICON.phone + '<i></i>';
    /* ★ 挂载时先显式设 left/top=0，让首次测量能正确反推环境偏移（与成就系统 pinBall 一致） */
    f.style.left = '0px';
    f.style.top = '0px';
    doc.body.appendChild(f);
    let dragFab = null;
    const SLOP = 5;
    f.addEventListener('pointerdown', e => {
      const rect = f.getBoundingClientRect();
      const cur = desiredFab || { x: rect.left, y: rect.top };
      dragFab = { startX: e.clientX, startY: e.clientY, origX: cur.x, origY: cur.y, moved: false };
      try { f.setPointerCapture(e.pointerId); } catch (err) {}
    });
    f.addEventListener('pointermove', e => {
      if (!dragFab) return;
      const dx = e.clientX - dragFab.startX, dy = e.clientY - dragFab.startY;
      if (!dragFab.moved && Math.abs(dx) + Math.abs(dy) < SLOP) return;
      dragFab.moved = true;
      const { w, h } = hostViewport();
      const rect = f.getBoundingClientRect();
      const fw = rect.width || 46, fh = rect.height || 46;
      desiredFab = {
        x: clamp(dragFab.origX + dx, 4, Math.max(4, w - fw - 4)),
        y: clamp(dragFab.origY + dy, 4, Math.max(4, h - fh - 4)),
      };
      pinFab();
    });
    f.addEventListener('pointerup', () => {
      if (!dragFab) return;
      const wasMoved = dragFab.moved;
      dragFab = null;
      if (wasMoved && desiredFab) {
        writeViewportPos(POS_FAB_KEY, desiredFab.x, desiredFab.y);
      } else {
        openPhone();
      }
    });
    f.addEventListener('contextmenu', e => { e.preventDefault(); openPanel(true); });
    f.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openPhone(); } });
  }
  if (!doc.getElementById('ph-mask')) {
    const m = doc.createElement('div');
    m.id = 'ph-mask';
    doc.body.appendChild(m);
    /* ★ v1.9.1：原本用 click 关窗。手机上点悬浮球时，浏览器会在同一次触摸
       序列的末尾补发一个 click，此时遮罩层已经出现并铺满视口，于是刚打开
       的面板会被这个"幽灵点击"立刻关掉（悬浮球离输入框近时尤为明显）。
       改用 pointerdown，并且只认落在遮罩自身上的触摸 —— 触发打开的那次
       触摸的 pointerdown 发生在遮罩出现之前，遮罩收不到，不会被误判；
       用户真想关窗时手指首次按下就命中遮罩，比 click 更跟手。 */
    m.addEventListener('pointerdown', e => {
      if (e.target !== m) return;
      openPanel(false);
    });
  }
  if (!doc.getElementById('ph-root')) {
    const p = doc.createElement('div');
    p.id = 'ph-root';
    p.setAttribute('role', 'dialog'); p.setAttribute('aria-labelledby', 'ph-title');
    p.dataset.skin = skinOf();
    p.innerHTML = skeleton();
    doc.body.appendChild(p);
  }
  applyMode();   // 设定模式（浮窗/面板）+ 用实测反推法摆位 + 同步遮罩
  /* ★ 挂载后立刻把悬浮球钉到默认位置（无闪烁） */
  pinFab();
  /* ★ 个别环境首帧量不到尺寸：重试几次 */
  let tries = 0;
  const retry = () => {
    tries += 1;
    const fab = hostDoc().getElementById('ph-fab');
    const r = fab && fab.getBoundingClientRect ? fab.getBoundingClientRect() : null;
    if (r && r.width >= 4) { pinFab(); return; }
    if (tries > 12) return;
    setTimeout(retry, 250);
  };
  setTimeout(retry, 120);
}

function reloadPhoneChat() {
  STORE = loadStore();
  logCache = { key: '', rows: [], names: [], floors: 0 }; logByName = null;
  resetLoreCache();
  uiSet({ chatWith: null, forumPost: null, search: '', logOpen: false });
  const doc = hostDoc();
  doc.querySelectorAll('#ph-input,#ph-root [name="replytext"]').forEach(el => { el.value = ''; });
  resetTradeCounter();
  STORE.net = Object.assign({}, obj(STORE.net), { lastSeen: '' });
  saveStore(); restyle(); renderAll(); ensureLore(true);
}
/** 打开小手机（浮窗 / 面板，由 STORE.launch 决定） */
function openPhone() {
  openPanel();
}

/* ============================== 启动 ============================== */
async function boot() {
  try {
    if (typeof waitGlobalInitialized === 'function') {
      await Promise.race([
        waitGlobalInitialized('Mvu'),
        new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), 4000)),
      ]).catch(() => {});
    }
  } catch (e) {}
  const existed = !!obj(getVariables(SCRIPT_OPT)[VAR_ROOT]).version;
  STORE = loadStore();
  if (!existed || STORE.version !== PHONE_VERSION) { STORE.version = PHONE_VERSION; saveStore(); }
  ensureDom();
  bindEvents();
  bindRepin();
  if (uiGet().open) openPanel(true); else renderAll();
  if (typeof eventOn === 'function') {
    try {
      eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => {
        renderAll();
        try { maybeAutoTrade(); } catch (e) { console.warn('[小手机] 自动操盘失败', e); }
        try { netAutoCheck(); } catch (e) { console.warn('[小手机] 仙网自动生成失败', e); }
      });
    } catch (e) {}
    try { eventOn(tavern_events.CHAT_CHANGED, reloadPhoneChat); } catch (e) {}
  }
  if (typeof appendInexistentScriptButtons === 'function') {
    appendInexistentScriptButtons([
      { name: BTN_NAME, visible: true },
      { name: RESET_BTN_NAME, visible: true },
    ]);
  }
  if (typeof eventOn === 'function' && typeof getButtonEvent === 'function') {
    /* ★ v1.9.1：手机端所有脚本按钮入口统一先收起键盘、再补两次延时收起。
       原因：ST 手机端在按钮点击后可能补一次自动聚焦到主输入框，单次 blur 拦不住。 */
    const guard = fn => () => {
      dismissKeyboard();
      setTimeout(dismissKeyboard, 80);
      setTimeout(dismissKeyboard, 240);
      return fn();
    };
    eventOn(getButtonEvent(BTN_NAME), guard(() => openPhone()));
    eventOn(getButtonEvent(RESET_BTN_NAME), guard(() => resetPhonePos()));
  }
  console.info('[小手机] v' + PHONE_VERSION + ' 就绪（悬浮球左键＝浮窗/面板，右键＝角落小面板；脚本按钮可重置位置）');
}

$(errorCatched(boot));
